#!/usr/bin/env bash
set -euo pipefail
# ============================================================
# Guild Sprint supervisor — generated by /gld sprint run (guild-plugin <PLUGIN_VERSION>)
# Design: design/guild/02-sprint.md §8. Duplicated from batch.md's supervisor by decision
# D10 (batch's own script is NOT modified); the invariants both must share are fenced by
# `# <!-- guild:supervisor-core:* -->` markers and compared by tests/sprint_supervisor_test.sh.
# ============================================================
#
# WHY THIS IS A TEMPLATE FILE AND NOT EMBEDDED IN run.md (batch embeds its script in the .md):
# it is ~2.5x batch's script, so embedding would push run.md past 1000 lines, and a real
# file can be checked with `bash -n` directly instead of only after fence extraction.
# run.md substitutes the <PLACEHOLDER> tokens and writes the result next to the harness.
#
# NO `cd`. The design's §8.4 wording says "cd <issue worktree>"; this implementation uses
# `git -C <path>` and a subshell for the child session instead. Reason: a supervisor that
# has cd'd into a worktree cannot then remove that worktree — `git worktree remove` succeeds
# and the NEXT command dies with `Unable to read current working directory` (exit 128,
# measured). Never holding a cwd inside the container removes that failure mode entirely.
#
# bash 3.2 (macOS /bin/bash) compatible: no `declare -A`, no `mapfile`, no `${x^^}`.
# The per-issue ledger therefore lives as one-line JSON in the tracking Issue marker and is
# read/written by python heredocs — `declare -A` passes `bash -n` and only dies at RUNTIME.

TRACKER="<TRACKER>"
ORDER=(<ORDER>)                       # execution order from sprint_dag.py --mode order
OWNER_REPO="<OWNER_REPO>"
DEFAULT_BRANCH="<DEFAULT_BRANCH>"
CONTAINER="<CONTAINER>"               # <repo-parent>/.gld-<repo>-sprint-<tracker>
HUMAN_REPO="<HUMAN_REPO>"             # the human's checkout — logs and memory live here
DAG="<DAG_PATH>"                      # .../commands/atoms/sprint_dag.py
HEARTBEAT_EVERY=600                   # seconds; §8.2 requires <= 10 min, also while waiting
WAIT_MAX=14400                        # 4h ceiling on ANY single rate-limit wait (measured
                                      # worst case ~115 min); see the clamp below for why
# Zero or more SIMPLE commands, each shell-quoted. Array, not a single string: config's
# `commands` entries are already allowed to be arrays of steps (init.md P2 §1), and an empty
# inline substitution is a PARSE-time error — `( cd "$WT" && <EMPTY> )` cannot be guarded at
# runtime. Each element is `eval`ed, which is safe here precisely because config normalisation
# forbids `$(…)`, `&&`, `|`, `;` and redirections in these values.
INSTALL_CMDS=(<INSTALL_CMDS>)

# ── Board projection config (03-sprint-board.md §7.2) ────────────────────────
# ⚠ THESE TEN VALUES NEVER TOUCH SHELL SOURCE. They come from `config.sprint.board`, i.e. from
# display names a human typed into the GitHub Projects UI, and this file has now been bitten by
# that three times:
#   • `VAR="<TOKEN>"` — `Done $(touch /tmp/PWNED)` executed at supervisor start, and a name
#     ending in a backslash swallowed the following lines and killed the script at LOAD time
#     under `set -u`: before the traps, before the empty-queue guard, before one gh call. A
#     board display name could stop the sprint from running at all (violating D2 and D9 at once).
#   • a quoted heredoc killed expansion and backslashes but NOT a newline — a value containing
#     one closed the heredoc early and everything after it became top-level shell (measured:
#     `INJECTED_CODE` printed, then rc=127 before the traps).
# `bash -n` was silent for all three on bash 3.2.57, so no syntax gate can catch this class.
#
# So the values are read from a DATA FILE that `run.md` writes with the Write tool. A newline
# in a value can now do nothing worse than produce a junk line the `case` below ignores. There
# is no token here to leave unrendered, either — the whole class is gone rather than patched.
BOARD_CONF="$HUMAN_REPO/.claude/guild/.gld-sprint-$TRACKER.board"

# ── Run window config (04-sprint-window.md §1.3) ─────────────────────────────
# Same directory as the script and the `.board`, in the HUMAN's checkout. Unconditionally
# initialised HERE, not in the window block below: the block only ASSIGNS when the file
# exists, and under `set -u` a bare `$WIN_START` on a repo without a window is
# `unbound variable` — exit 1 before the first Issue (measured, §7 L).
WINDOW_CONF="$HUMAN_REPO/.claude/guild/.gld-sprint-$TRACKER.window"
WIN_START=""      # integer 0..2359, or "" for "no window"
WIN_END=""        # integer 0..2359
WIN_RAW=""        # the literal `HH:MM-HH:MM`, for the ledger and for messages
WIN_TOKEN=""      # zero-padded 4-digit start, for the `waiting-for-window-<HHMM>` state

BOARD_NUMBER=""; BOARD_OWNER=""; BOARD_FIELD=""; BOARD_FIELD_NEEDS_HUMAN=""
BOARD_VERIFIED_AS=""
# Column display names as FIVE SCALARS, not a map: this file is bash 3.2 compatible and
# `declare -A` passes `bash -n` while dying at runtime (see the header). `backlog`/`issues`
# are absent on purpose — the supervisor never writes them (§5.2), `plan` does.
BOARD_COL_READY=""; BOARD_COL_IN_PROGRESS=""; BOARD_COL_BLOCKED=""
BOARD_COL_IN_REVIEW=""; BOARD_COL_DONE=""
BOARD_CONF_BAD=""
BOARD_CONF_MISSING=0     # "there is no file" — the normal board-off case, and it is SILENT
BOARD_OFF_REASON=""      # ⚠ WHY the board never came up. These paths used to signal only with
                         # an `echo` on the supervisor's stdout — which `daily` states plainly it
                         # cannot read. A six-hour run against an untouched board then rendered
                         # as "투영 기록 없음", indistinguishable from "the run has not started".
                         # D9 forbids absorbing the FACT of absorption; this is that fact.
BOARD_WAS_ON=0           # "the board was on when this run started" — survives board_breaker

if [ -f "$BOARD_CONF" ] && [ ! -r "$BOARD_CONF" ]; then
  # `[ -f ]` is true and the redirect below then fails with a raw bash `Permission denied` and
  # no WARN of ours. Name it instead.
  BOARD_CONF_BAD="board config exists but is not readable"
elif [ -f "$BOARD_CONF" ]; then
  # `IFS='='` + `read -r k v` splits on the FIRST `=` only, so a display name may contain one.
  # ⚠ `|| [ -n "$bk" ]` consumes an UNTERMINATED final line. Without it `read` returns non-zero
  # on a last line with no newline and the loop body never runs for it — so the file's last key
  # is silently dropped, and if that key is `number` the whole board goes off with nothing said.
  # `run.md` lets the ten lines come in any order, so `number` last is a legal document.
  while IFS='=' read -r bk bv || [ -n "$bk" ]; do
    # `IFS='='` REPLACES the default whitespace set, so nothing is trimmed: `  number=7` would
    # match no `case` arm. Strip a CR (CRLF files) and surrounding blanks from the key.
    bk="${bk%$'\r'}"; bk="${bk#"${bk%%[![:space:]]*}"}"; bk="${bk%"${bk##*[![:space:]]}"}"
    bv="${bv%$'\r'}"
    case "$bk" in
      # ⚠ `number` is the ONLY value that gets its blanks trimmed. It is numeric, so whitespace
      # cannot be meaningful there. Display names are kept byte-exact: whether GitHub trims a
      # trailing space in an option name is UNMEASURED, and trimming it here would make Guild
      # write a name the board does not have.
      number)            BOARD_NUMBER="${bv#"${bv%%[![:space:]]*}"}"
                         BOARD_NUMBER="${BOARD_NUMBER%"${BOARD_NUMBER##*[![:space:]]}"}" ;;
      owner)             BOARD_OWNER="$bv" ;;
      field)             BOARD_FIELD="$bv" ;;
      field_needs_human) BOARD_FIELD_NEEDS_HUMAN="$bv" ;;
      verified_as)       BOARD_VERIFIED_AS="$bv" ;;
      col_ready)         BOARD_COL_READY="$bv" ;;
      col_in_progress)   BOARD_COL_IN_PROGRESS="$bv" ;;
      col_blocked)       BOARD_COL_BLOCKED="$bv" ;;
      col_in_review)     BOARD_COL_IN_REVIEW="$bv" ;;
      col_done)          BOARD_COL_DONE="$bv" ;;
    esac
  done < "$BOARD_CONF"
else
  BOARD_CONF_MISSING=1
fi

# ⚠ VALIDATE, then treat anything unusable as "board off". Three failure modes converge here:
# a renderer that never wrote the file, a project number that is not a number, and a required
# display name that is empty. Either way the right answer is D2's off path plus ONE loud line,
# never a silent six-hour run against a project that does not exist.
case "$BOARD_NUMBER" in
  "")           : ;;                                  # board genuinely off — say nothing
  *[!0-9]*)     BOARD_CONF_BAD="number=$BOARD_NUMBER"; BOARD_NUMBER="" ;;
esac
# ⚠ A file that EXISTS but yielded no `number` must be loud. Without this the empty case above
# says nothing on purpose (that is D2's board-off path) and a garbage, truncated or
# half-written file becomes a silent six-hour run with an untouched board — which is exactly
# what the comment above claims cannot happen.
if [ "$BOARD_CONF_MISSING" = 0 ] && [ -z "$BOARD_NUMBER" ] && [ -z "$BOARD_CONF_BAD" ]; then
  # ⚠ basename, not $BOARD_CONF. This lands in the ledger as `board_off_reason` and
  # `marker_write` renders the whole ledger into a GitHub issue comment — the full path is
  # `/Users/<name>/…`, which INV5 forbids leaving the machine (04-sprint-window.md §6.5).
  BOARD_CONF_BAD="no usable \`number=\` line in $(basename "$BOARD_CONF")"
fi
if [ -n "$BOARD_NUMBER" ]; then
  # ⚠ BOARD_FIELD_NEEDS_HUMAN belongs on this list. It was left off, and `board_col` uses it
  # unconditionally — so an empty value produced `item-edit --field "" --clear` on every single
  # write, all of them failing, while `board_col`'s comment claimed load-time validation had
  # already forced the board off.
  for bn in "$BOARD_OWNER" "$BOARD_FIELD" "$BOARD_FIELD_NEEDS_HUMAN" \
            "$BOARD_COL_READY" "$BOARD_COL_IN_PROGRESS" \
            "$BOARD_COL_BLOCKED" "$BOARD_COL_IN_REVIEW" "$BOARD_COL_DONE"; do
    if [ -z "$bn" ]; then
      BOARD_CONF_BAD="a required board name is empty"; BOARD_NUMBER=""; break
    fi
  done
fi
# ⚠ Only complain when the file was supposed to describe a live board. A board-less repo has no
# file and that is the normal case for every existing user — a WARN there would be noise on
# every run. `run.md` writes the file only when `config.sprint.board` is set.
# A dedicated flag, not a string comparison against the message: comparing the reason text
# against a reconstructed sentence is the kind of check that breaks the first time the sentence
# is reworded, and it broke here.
if [ -n "$BOARD_CONF_BAD" ] && [ "$BOARD_CONF_MISSING" = 0 ]; then
  echo "[sprint] WARN: board config unusable ($BOARD_CONF_BAD) — running WITHOUT the board"
  BOARD_OFF_REASON="config:$BOARD_CONF_BAD"
fi
# ⚠ `if`, not `[ … ] && …`. ⚠ **The reason stated here until now was wrong, and the
# conclusion is unchanged anyway.** A `[ … ] && …` returning 1 is fatal under `set -e` only
# when it is the LAST statement of a function or of the script — in the middle of a list bash
# does not exit (measured, 04-sprint-window.md §7 M). So this line is not, today, one line away
# from killing every board-less run. Keep the `if` regardless: the form that is safe only
# because of WHERE IT SITS becomes fatal the moment someone moves it, and `in_window`'s
# `[ -z "$WIN_START" ] && return 0` is exactly that line. Do not "simplify" either of them,
# and do not re-derive the rule from the old, false justification.
if [ -n "$BOARD_NUMBER" ]; then BOARD_WAS_ON=1; fi

RUNDIR="$HUMAN_REPO/.claude/guild/.sprint-logs/$TRACKER"
D="$RUNDIR/dag"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
mkdir -p "$D"

# ── 보드 투영 (03-sprint-board.md §5.2·§7.2) ─────────────────────────────────
# Defined HERE, before `cleanup` and the empty-queue guard, because P7 lives inside the
# EXIT trap: putting these after the guard leaves a window where the trap could reference
# an undefined function. `${ISSUE:-}` in P7 already makes the empty-queue path a no-op, but
# ordering it away is cheaper than reasoning about it.
BOARD_FAILS=0            # gh failures, absorbed (D9) but COUNTED — see heartbeat
BOARD_UNKNOWN_COL=0      # config names a column the board does not have — a UI rename, almost
                         # always. Rendered as "config와 어긋난 컬럼 이름", never as our bug.
BOARD_BUGS=0             # unknown column token = OUR bug; kept apart from gh failures so
                         # "board failures: N" stays a scope/rate-limit signal for the human
BOARD_LAST_OK=1          # last project_set outcome; board_col caches only on success
BOARD_PROJECT_ID=""      # project node id; node-ID writes cost 1 point instead of 104
BOARD_STREAK=0           # CONSECUTIVE COLUMN write failures — resets on any column success
BOARD_RSN_STREAK=0       # ... and the same for the reason field, tracked apart (a broken
                         # annotation must not cost the human the column layout)
BOARD_STREAK_MAX=10      # ... and at this many, board_breaker turns the board off
: > "$D/board.rsn"       # reason cache, one line per issue: `<issue> <column> <reason>`.
                         # Separate from board.txt on purpose: P7's guard asks "what column
                         # does this card show", and a file answering two questions lied both
                         # ways once already (v13).
: > "$D/board.txt"       # column cache, ONE LINE PER ISSUE, rewritten.
                         # ⚠ Truncated every run on purpose: `$D` survives a run that needs
                         # re-running (it is only removed when FAILED+INCOMPLETE+BLOCKED==0),
                         # so a stale `101 in_progress` from the previous run would make P1
                         # skip its write and leave the card wherever it was.

# ── Node-ID addressing (§7.5, v18) ───────────────────────────────────────────
# ⚠ WHY: a name-addressed write costs **104 GraphQL points**; the node-ID form costs **1**.
# Both measured four times on a live project. The hourly budget is 5000, so the name form
# allows ~48 writes an hour — and a 12-member run makes several per member, before the failure
# retry path triples it. The supervisor shares that budget with `refresh_dag_input`'s
# `gh pr list`/`gh issue list`, so board cost turning into `dag-input-failed` was not
# hypothetical. §7.5's old accounting counted gh invocations and never points.
#
# The preparation is paid ONCE per run: `project view` = 2 points, `field-list --limit 100` = 101,
# `item-list --limit 200` = 201. After that every projection is 1 point.
board_resolve() {        # populates BOARD_PROJECT_ID, $D/board.fld, $D/board.opt, $D/board.itm
  # ⚠ CALLED ONCE PER RUN. `board.itm` is truncated here, so a second call would discard every
  # id `board_item_of` discovered via `item-add` and pay for them again. Harmless today (one
  # call site, right after the account check) and deliberately noted for whoever adds a second.
  [ -n "$BOARD_NUMBER" ] || return 0
  # ⚠ Data through a FILE, program through the heredoc. `gh … | "$PY" - <<'PY'` does NOT work:
  # the heredoc IS stdin, so it feeds the program and the pipe is discarded — python then reads
  # an empty stdin and every parse silently yields nothing. Measured while writing this.
  gh project view "$BOARD_NUMBER" --owner "$BOARD_OWNER" --format json \
    > "$D/board.view.json" 2>/dev/null || : > "$D/board.view.json"
  BOARD_PROJECT_ID=$("$PY" - "$D/board.view.json" <<'PY' 2>/dev/null || true
import json, sys
try:
    print((json.load(open(sys.argv[1])) or {}).get("id") or "")
except Exception:
    print("")
PY
)
  if [ -z "$BOARD_PROJECT_ID" ]; then
    echo "[sprint] WARN: cannot read project $BOARD_NUMBER — running WITHOUT the board"
    BOARD_OFF_REASON="project-unreadable"; BOARD_NUMBER=""; return 0
  fi
  # ⚠ 100, not 25. A new project already carries 13 built-in fields plus Guild's 5, so seven
  # human-added fields crossed the old cap — and a short read is FATAL here (the board goes off
  # for the whole run) while `sprint board`'s own diagnostic reads at 100 and reports the same
  # board healthy. One limit, in all three readers.
  gh project field-list "$BOARD_NUMBER" --owner "$BOARD_OWNER" --limit 100 --format json \
    > "$D/board.fl.json" 2>/dev/null || : > "$D/board.fl.json"
  "$PY" - "$D/board.fl.json" "$D/board.fld" "$D/board.opt" "$BOARD_FIELD" <<'PY' 2>/dev/null || true
import json, sys
src, fld, opt, colname = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
try:
    d = json.load(open(src)) or {}
except Exception:
    d = {}
fields = d.get("fields") or []
total = d.get("totalCount")
# A short list means a field we need may be missing from it, and "missing" is indistinguishable
# from "renamed" downstream. Write nothing rather than a partial map.
if total is not None and len(fields) != total:
    fields = []
with open(fld, "w") as fh, open(opt, "w") as oh:
    for f in fields:
        name = f.get("name") or ""
        # ⚠ `\n` too, not just `\t`. A field named "Sprint\nGuild board" writes two lines and the
        # second one hijacks the real column field's key — the column write then goes to the
        # wrong field id. The config loader already treats a newline in a display name as a real
        # input class; this is the same class one layer down.
        if not name or "\t" in name or "\n" in name:
            continue
        fh.write("%s\t%s\n" % (name, f.get("id") or ""))
        if name == colname:
            for o in f.get("options") or []:
                if o.get("name") and "\t" not in o["name"] and "\n" not in o["name"]:
                    oh.write("%s\t%s\n" % (o["name"], o.get("id") or ""))
PY
  if [ ! -s "$D/board.fld" ]; then
    echo "[sprint] WARN: cannot read the board's fields — running WITHOUT the board"
    BOARD_OFF_REASON="fields-unreadable"; BOARD_NUMBER=""; return 0
  fi
  # issue -> project item id, from one read. Cards `plan` seeded are all here; anything else
  # is added on first touch.
  # ⚠ Keep `totalCount`. The old projection reduced the envelope to a bare array, so a board
  # with more than the limit yielded a partial `board.itm` with no way to know — and §10 says
  # the board accumulates forever, so any fixed limit WILL be crossed. `board_write.py` compares
  # and re-reads; this side just says so and degrades (correctness survives — `item-add` is
  # idempotent and returns the right id — but every missing card costs one extra mutation).
  gh project item-list "$BOARD_NUMBER" --owner "$BOARD_OWNER" --limit 200 --format json \
      --jq '{items: [.items[] | {id: .id, n: .content.number, r: .content.repository}], totalCount: .totalCount}' \
    > "$D/board.il.json" 2>/dev/null || : > "$D/board.il.json"
  : > "$D/board.short"
  "$PY" - "$D/board.il.json" "$D/board.itm" "$OWNER_REPO" "$D/board.short" <<'PY' 2>/dev/null || true
import json, sys
src, out, repo, short = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
try:
    d = json.load(open(src)) or {}
except Exception:
    d = {}
items = d.get("items") or []
total = d.get("totalCount")
with open(out, "w") as fh:
    for it in items:
        if it.get("n") is None or it.get("r") != repo:
            continue                      # drafts have no number; other repos are not ours
        # ⚠ Skip an empty id. Writing `101 ` poisons the cache: `awk '$1==n {print $2}'` returns
        # empty for that issue forever, so every `project_set` re-runs `item-add` AND appends a
        # duplicate line — the file grows without bound.
        if not it.get("id"):
            continue
        fh.write("%s %s\n" % (it["n"], it["id"]))
if total is not None and len(items) != total:
    open(short, "w").write("%d/%d\n" % (len(items), total))
PY
  [ -f "$D/board.itm" ] || : > "$D/board.itm"

  if [ -s "$D/board.short" ]; then
    echo "[sprint] NOTE: the board has more cards than one page ($(cat "$D/board.short")) —" \
         "cards past the first page cost one extra call each; projection is still correct"
    ledger_set board_items_truncated "\"$(cat "$D/board.short")\"" 2>/dev/null || true
  fi

  # ⚠ CHECK THE COLUMN FIELD HERE, not per write. Without this, a field renamed or deleted in
  # the UI made every `project_set` fall into the no-id branch — `BOARD_FAILS++`, never
  # `BOARD_UNKNOWN_COL++` — so `daily` said *"연속 실패로 투영을 중단했습니다"* and pointed the
  # human at `project` scope or a rate limit instead of at config. It also PAID for it: 
  # `board_item_of` runs first, so each of the ten doomed writes did a real `item-add`, adding
  # cards to a board nothing could then write to. Measured: 22 gh calls, 10 of them mutations.
  if [ -z "$(board_id_of "$BOARD_FIELD" "$D/board.fld")" ]; then
    echo "[sprint] WARN: column field \"$BOARD_FIELD\" is not on the board — running WITHOUT the board"
    BOARD_OFF_REASON="column-field-missing"; BOARD_NUMBER=""; return 0
  fi
  return 0
}

board_id_of() {          # board_id_of <name> <tab-file> -> id, or ""
  # ⚠ `ENVIRON`, not `-v`. `awk -v k=…` performs ESCAPE-SEQUENCE PROCESSING on the value, so a
  # display name containing a backslash (`C:\temp` -> `C:<TAB>emp`) silently never matches and
  # the lookup returns empty — counted as a failure, blamed on scope or rate limit. Backslashes
  # in board display names are not hypothetical here: this file's header records one that killed
  # the script at LOAD time. `board_write.py` (a python dict lookup) resolves the same name
  # fine, so `plan` would fill the board while the supervisor could not move a single card.
  k="$1" awk -F'\t' '$1==ENVIRON["k"] {print $2; exit}' "$2" 2>/dev/null || true
}

board_item_of() {        # board_item_of <issue> -> project item id, adding the card if needed
  local id
  id=$(awk -v n="$1" '$1==n {print $2; exit}' "$D/board.itm" 2>/dev/null || true)
  if [ -z "$id" ]; then
    # `plan` seeds the members, but `--setup` can be run mid-sprint and a card can be deleted
    # by hand. `item-add` is idempotent (same item id, exit 0 — measured) and returns the id.
    gh project item-add "$BOARD_NUMBER" --owner "$BOARD_OWNER" \
      --url "https://github.com/$OWNER_REPO/issues/$1" --format json \
      > "$D/board.add.json" 2>/dev/null || : > "$D/board.add.json"
    id=$("$PY" - "$D/board.add.json" <<'PY' 2>/dev/null || true
import json, sys
try:
    print((json.load(open(sys.argv[1])) or {}).get("id") or "")
except Exception:
    print("")
PY
)
    if [ -n "$id" ]; then printf '%s %s\n' "$1" "$id" >> "$D/board.itm"; fi
  fi
  printf '%s' "$id"
}

project_set() {          # project_set <issue> <field> [value]   (omitted/empty => --clear)
  [ -n "$BOARD_NUMBER" ] || return 0
  local item fid oid flag
  item=$(board_item_of "$1")
  fid=$(board_id_of "$2" "$D/board.fld")
  if [ -z "$item" ] || [ -z "$fid" ]; then
    # No id, no 1-point write. Falling back to the 104-point name form here would reintroduce
    # exactly the cost this change removes, and on the cards that are hardest to reach anyway.
    BOARD_FAILS=$((BOARD_FAILS+1)); BOARD_LAST_OK=0; return 0
  fi
  # `${3:-}` not `$3`: a value-less call (clearing a reason) must not die under `set -u`.
  if [ -n "${3:-}" ]; then
    if [ "$2" = "$BOARD_FIELD" ]; then
      oid=$(board_id_of "$3" "$D/board.opt")
      if [ -z "$oid" ]; then
        # ⚠ ITS OWN COUNTER, not `BOARD_BUGS`. The overwhelmingly likely cause is a human
        # renaming a column in the GitHub UI without updating config — the most probable board
        # fault in a months-old project — and `BOARD_BUGS` is rendered as *"Guild 버그"*, i.e.
        # "report this to us", when the fix is a one-line config edit.
        BOARD_UNKNOWN_COL=$((BOARD_UNKNOWN_COL+1)); BOARD_LAST_OK=0; return 0
      fi
      flag=(--single-select-option-id "$oid")
    else
      # The four data fields are TEXT by `board.md`'s spec. `--value` exists only alongside
      # `--field` (the name form), so TEXT is what a node-ID write sends.
      flag=(--text "$3")
    fi
  else
    flag=(--clear)
  fi
  # ⚠ `|| { … }` is REQUIRED and must not be an `if ! …; then` body: that body is NOT exempt
  # from `set -e`, and without the guard a missing `project` scope killed the whole run at the
  # first member.
  gh project item-edit --id "$item" --project-id "$BOARD_PROJECT_ID" --field-id "$fid" \
    "${flag[@]}" >/dev/null 2>&1 \
    || { BOARD_FAILS=$((BOARD_FAILS+1)); BOARD_LAST_OK=0; return 0; }
  BOARD_LAST_OK=1
  return 0
}

# ⚠ Absorbing failures is D9; continuing to PAY for them is not something D9 asks for.
# ⚠ The arithmetic here was rewritten in v18 and the old numbers were wrong twice over.
# A `board_col` is now at most 2 `item-edit` plus, on a first touch, 1 `item-add` — the
# edit → add → edit retry is gone. What makes a dead board expensive is not the call count but
# that `board_col` caches only on success, so P1 re-fires on every retry (up to 12 split passes
# and 6 rate-limit waits per member) and each attempt still spends GraphQL points. The
# supervisor's own correctness calls (`gh pr list` / `gh issue list` in `refresh_dag_input`)
# share that budget, so board pressure can turn into a real `dag-input-failed`, which
# terminal-blocks every dependant. So: after N consecutive COLUMN failures, stop calling. The
# counters and the reason survive in the ledger.
board_breaker() {   # board_breaker <0|1: did this board_col succeed entirely>
  if [ "$1" = 1 ]; then BOARD_STREAK=0; return 0; fi
  BOARD_STREAK=$((BOARD_STREAK+1))
  [ "$BOARD_STREAK" -ge "$BOARD_STREAK_MAX" ] || return 0
  echo "[sprint] NOTE: board disabled after $BOARD_STREAK consecutive failures — the run continues"
  # ⚠ FAILS + UNKNOWN_COL, not FAILS alone. A renamed column never touches `BOARD_FAILS`, so a
  # board disabled entirely by renames recorded `board_disabled_after: 0` and `daily` rendered
  # *"연속 실패로 투영을 중단했습니다 (누적 실패 0건)"* — a sentence that refutes itself.
  ledger_set board_disabled_after "$((BOARD_FAILS + BOARD_UNKNOWN_COL))" 2>/dev/null || true
  BOARD_NUMBER=""          # every helper's first line short-circuits on this
  return 0
}

board_col() {            # board_col <issue> <column-token> [reason-token]
  [ -n "$BOARD_NUMBER" ] || return 0
  local name=""
  case "$2" in
    ready)       name="$BOARD_COL_READY" ;;
    in_progress) name="$BOARD_COL_IN_PROGRESS" ;;
    blocked)     name="$BOARD_COL_BLOCKED" ;;
    in_review)   name="$BOARD_COL_IN_REVIEW" ;;
    done)        name="$BOARD_COL_DONE" ;;
    # Not silent: an unknown token is a code bug, and D9 forbids absorbing the FACT of
    # absorption. Counted separately from gh failures so the two stay distinguishable.
    *)           BOARD_BUGS=$((BOARD_BUGS+1)); return 0 ;;
  esac
  # An empty display name would reach `project_set` as a value-less call, i.e. `--clear`,
  # which silently moves the card to the NULL BUCKET — the `Issues` column, "needs
  # refinement" — while the cache records the intended token and neither counter moves.
  # Load-time validation already forces the board off in that case; this is the second lock,
  # because a card that lies with nothing counted is the one outcome D9 rules out.
  if [ -z "$name" ]; then BOARD_BUGS=$((BOARD_BUGS+1)); return 0; fi
  # Column write is deduped; the reason is not. P1 fires on every retry (up to 12 split
  # passes, 6 rate-limit waits), so the column cache is where the savings are — while the
  # reason is written at most once per outcome.
  BOARD_LAST_OK=1          # a deduped (skipped) column write counts as "nothing went wrong"
  if ! grep -qxF "$1 $2" "$D/board.txt" 2>/dev/null; then
    project_set "$1" "$BOARD_FIELD" "$name"
    if [ "$BOARD_LAST_OK" = 1 ]; then
      grep -v "^$1 " "$D/board.txt" > "$D/board.tmp" 2>/dev/null || :
      printf '%s %s\n' "$1" "$2" >> "$D/board.tmp"
      mv "$D/board.tmp" "$D/board.txt"
      # ⚠ Record WHEN A CARD ACTUALLY MOVED — inside the cache-miss branch, so a fully deduped
      # `board_col` that makes zero gh calls does not bump it. Every reader used to derive
      # "마지막 투영" from the marker's `heartbeat`, which `marker_write` writes regardless of
      # what the board did; this is the only value that makes that clause honest, and it is also
      # what distinguishes "no failures because everything worked" from "no failures because
      # nothing was attempted" (the dependency-blocked path writes nothing at all, by design).
      ledger_set board_last_write "$(date +%s)" 2>/dev/null || true
    fi
  fi
  # ⚠ THE STREAK FOLLOWS THE COLUMN WRITE ONLY. Feeding it the AND of both writes meant a
  # broken *reason* field — a `Needs human` created as a single-select instead of TEXT, or a
  # per-field permission — disabled the PRIMARY projection after 10 members, even though every
  # column write had landed (measured: 10 successful column writes, board switched off). The
  # columns are what the human reads; the reason is an annotation. Degrade the annotation
  # instead: stop writing it and keep the columns going.
  local col_ok="$BOARD_LAST_OK"

  # ⚠ Guarded. `board_col` used this unconditionally, so an empty field name produced
  # `item-edit --field "" --clear` on every write — 20 failures out of 20, none of them
  # anybody's fault but ours. Load-time validation now forces the board off in that case;
  # this is the second lock.
  # ⚠ The reason IS deduped, on the same (issue, column, reason) triple. It used to be written
  # unconditionally on every call, which is O(N x sweeps) extra gh calls — and that is the same
  # budget the breaker trips on (10 consecutive failures) and the same budget
  # `refresh_dag_input`'s correctness reads share. `board_sweep_merged` alone re-clears the
  # reason for every merged member at three separate call sites.
  if [ -n "$BOARD_FIELD_NEEDS_HUMAN" ] \
     && ! grep -qxF "$1 $2 ${3:-}" "$D/board.rsn" 2>/dev/null; then
    project_set "$1" "$BOARD_FIELD_NEEDS_HUMAN" "${3:-}"
    if [ "$BOARD_LAST_OK" = 1 ]; then
      grep -v "^$1 " "$D/board.rsn" > "$D/board.rsn.tmp" 2>/dev/null || :
      printf '%s %s %s\n' "$1" "$2" "${3:-}" >> "$D/board.rsn.tmp"
      mv "$D/board.rsn.tmp" "$D/board.rsn"
      BOARD_RSN_STREAK=0
    else
      # ⚠ Degrade, do not disable. After N consecutive reason failures stop writing the reason
      # and keep projecting columns — an annotation nobody can write is worth less than the
      # column layout, and turning the board off would cost the human both.
      BOARD_RSN_STREAK=$((BOARD_RSN_STREAK+1))
      if [ "$BOARD_RSN_STREAK" -ge "$BOARD_STREAK_MAX" ]; then
        echo "[sprint] NOTE: reason field \"$BOARD_FIELD_NEEDS_HUMAN\" is unwritable — columns continue without it"
        ledger_set board_reason_disabled 1 2>/dev/null || true
        BOARD_FIELD_NEEDS_HUMAN=""
      fi
    fi
  fi

  # ⚠ THE STREAK IS COUNTED PER board_col, NOT PER project_set. Counting per call meant either
  # of the two writes succeeding reset it, so the streak only ever reached the limit when EVERY
  # gh call failed — i.e. the rate-limit case. The common partial outage (the column field
  # renamed in the UI, or a per-field permission) left the board "on" forever: measured at 240
  # gh calls over 60 board_col with the column write failing every time, versus 30 when
  # everything failed. The partial outage is exactly the case the breaker was written for.
  board_breaker "$col_ok"
  return 0
}

board_sweep_merged() {   # P5/P6 — cards for members whose PR is already MERGED
  [ -n "$BOARD_NUMBER" ] || return 0
  [ -f "$D/run.json" ] || return 0
  # `run.json`, NOT `prs.json`: the latter is the raw `gh pr list` payload with no `issue`
  # key and no member filter. The issue<->PR attribution (closingIssuesReferences, then a
  # unique issue-number token in the head branch) already happened in the python pass.
  "$PY" - "$D/run.json" > "$D/merged.txt" 2>/dev/null <<'PY' || : > "$D/merged.txt"
import json, sys
try:
    d = json.load(open(sys.argv[1]))
except Exception:
    sys.exit(0)
for pr in d.get("prs") or []:
    if pr.get("state") == "MERGED" and pr.get("issue") is not None:
        print(pr["issue"])
PY
  while read -r n; do
    # ⚠ `if`, not `[ … ] && …`: `done` in argument position parses correctly today, but adding a
    # `;` before it makes this a syntax error and `bash -n` exits 0 on those (bash 3.2.57).
    if [ -n "$n" ]; then board_col "$n" done; fi
  done < "$D/merged.txt"
  return 0
}

board_col_of() {         # board_col_of <issue> -> last column token written, or ""
  [ -f "$D/board.txt" ] || { printf ''; return 0; }
  awk -v n="$1" '$1==n {print $2}' "$D/board.txt" | tail -1
}

PY="${PY:-python3}"
HOSTNAME_S="$(hostname 2>/dev/null || echo unknown)"

SUP="$CONTAINER/supervisor"      # re-derived in ensure_container after normalisation

# ─────────────────────────────────────────────────────────────────────────────
# §8.1a — the container AND the supervisor worktree. Called AFTER the empty guard.
# ─────────────────────────────────────────────────────────────────────────────
# Deliberately not run at load time: a run with nothing to do must not create a worktree, and
# a repo state that makes `worktree add` impossible must not turn "no members to run" into a
# failure. Everything that touches $SUP happens inside the main loop, after this call.
ensure_container() {
  # `git worktree list --porcelain` prints REALPATHs. $CONTAINER arrives from config or the
  # $TMPDIR fallback, and on macOS BOTH `/tmp` and `$TMPDIR` are symlinks (`/private/tmp`,
  # `/private/var/folders/...`) — so an unnormalised path never equals what `worktree list`
  # reports, and worktree_acquire's "registered?" test then calls every live worktree an
  # unregistered stray and refuses it. Normalise ONCE here so every later compare uses one form.
  mkdir -p "$CONTAINER" 2>/dev/null \
    || { echo "[sprint] FAIL: cannot create container $CONTAINER" >&2; return 1; }
  CONTAINER="$(cd "$CONTAINER" && pwd -P)"
  SUP="$CONTAINER/supervisor"

  # Every `git -C "$SUP"` needs this to exist. Without it the run is a silent no-op: each Issue
  # reports "worktree unavailable" and its dependents report `dep-no-branch`, which reads as
  # ordinary waiting rather than as a failure (measured — a 2-member run reported
  # `Done: 0  Blocked: 1  Failed: 1` and then deleted its own script). `--detach` because it
  # must not hold a branch the human already has checked out.
  # ⚠ Registered is not enough — the DIRECTORY has to be there. A `$TMPDIR` fallback container
  # can be cleaned while the sprint is between runs (worktree_acquire says so about its own
  # worktrees and prunes; this function did not), and then every `git -C "$SUP"` fails with
  # `cannot change to …` while the run reports each Issue as "worktree unavailable" and its
  # dependants as merely blocked. Prune the stale registration and fall through to re-create.
  if git -C "$HUMAN_REPO" worktree list --porcelain 2>/dev/null | grep -qxF "worktree $SUP"; then
    [ -d "$SUP" ] && return 0
    prune_safe
  fi
  if [ -e "$SUP" ]; then
    echo "[sprint] FAIL: $SUP exists but is not a registered worktree — resolve by hand" >&2
    return 1
  fi
  git -C "$HUMAN_REPO" worktree add --detach "$SUP" "$DEFAULT_BRANCH" >/dev/null 2>"$D/sup.err" \
    || git -C "$HUMAN_REPO" worktree add --detach "$SUP" HEAD >/dev/null 2>>"$D/sup.err" \
    || { echo "[sprint] FAIL: cannot create supervisor worktree — $(head -1 "$D/sup.err" 2>/dev/null || true)" >&2
         return 1; }
  return 0
}

# Protect sprint infra from subagents' `git stash -u`, and keep the memory symlink from
# showing as untracked (§8.1b: `.gitignore`'s `memory/` is a DIRECTORY pattern and does not
# match a symlink, so without this the worktree is dirty and `git worktree remove` refuses).
# `--git-path` resolves correctly from a normal checkout and from a worktree.
EXCLUDE="$(git -C "$HUMAN_REPO" rev-parse --git-path info/exclude 2>/dev/null || true)"
# ⚠ `rev-parse --git-path` returns a path relative to THE REPO, not to $PWD — and this script
# deliberately never cd's, so the relative form resolved against the launch directory instead.
# Measured: it created a stray `.git/info/exclude` wherever the supervisor was started and the
# three exclusions never reached the real repo, so the memory symlink stayed untracked, EVERY
# issue worktree was judged dirty, and no worktree was ever removed. (From a linked worktree
# git returns an absolute path, so both shapes have to be handled.)
case "$EXCLUDE" in
  ""|/*) ;;
  *) EXCLUDE="$HUMAN_REPO/$EXCLUDE" ;;
esac
if [ -n "$EXCLUDE" ]; then
  mkdir -p "$(dirname "$EXCLUDE")"; touch "$EXCLUDE"
  for E in ".claude/guild/.gld-sprint-$TRACKER.sh" ".claude/guild/.sprint-logs" ".claude/guild/memory"; do
    grep -qxF "$E" "$EXCLUDE" || echo "$E" >> "$EXCLUDE"
  done
fi

# <!-- guild:supervisor-core:selfdelete -->
# Self-delete on a COMPLETED run only (no trap can catch SIGKILL). A run that died — crash, a
# `kill`, a genuine failure — keeps its script: that script is what re-runs it and shows what
# it was going to do.
#
# ⚠ **Ctrl-C is not one of the cases, and cannot be.** run.md starts this script as a
# BACKGROUND job of a non-interactive shell, which inherits SIGINT as SIG_IGN — and a signal
# ignored on entry cannot be trapped or reset. Measured: an INT handler that calls `exit` is
# never reached and the run sleeps straight through. `kill` (SIGTERM) is how a human stops it.
#
# ⚠ **And `kill` is not immediate — it takes effect at the next boundary, not now.** bash defers
# a trap while a foreground command runs, and the child `claude` session is a separate process
# that the signal does not reach. Measured: a TERM sent mid-session was handled only when the
# session ended, and one sent inside `hb_sleep` waited out the sleep chunk (up to
# HEARTBEAT_EVERY). So a `kill` means *"stop after the current Issue"*, and in the meantime the
# child finishes its commit, push and PR. That is deliberate: signalling the process GROUP would
# kill the child mid-spine, leaving a branch with no commit and a half-written PR that no resume
# path is designed to clean up. Say "stop after the current issue" to the human, never "stopped".
SCRIPT_PATH="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"
COMPLETED=0
FINISHED=0
# ⚠ WHY this lives HERE and not next to the window block: `cleanup` reads it, and every test
# harness that sources a cut through the closing selfdelete marker must see it ASSIGNED.
# Declared in the window block instead, `${HALT_REASON:-}` would be the only defence and the
# P7 gate below would be testing a default rather than a value (04-sprint-window.md §4.2).
# `halted:interrupted` was a single bit for every abnormal exit; on a run that lasts DAYS it is
# the only diagnostic channel there is, so each exit path names itself.
HALT_REASON=""    # "" = a clean ending. Otherwise: window-invalid · marker-unwritable ·
                  # container-lost · sigTERM · sigHUP. `cleanup` renders `halted:<this>`.
cleanup() {
  # `marker_write` may not be defined yet if we die before its definition; `|| true` covers
  # both that (127) and a network failure. A failed final marker must not mask the real exit.
  # ⚠ Only a run that did NOT reach its own ending gets the halted marker. Writing it
  # unconditionally overwrote `state: finished` on EVERY clean run, because the trap fires
  # last — a completed sprint was then recorded as interrupted (measured).
  #
  # ⚠ **THIS GATE IS UNCHANGED, and that is the design decision** (04-sprint-window.md §4.2b).
  # An earlier draft widened it to `|| [ -n "${HALT_REASON:-}" ]` so the three halt paths below
  # could still repair their card. That is wrong in both directions: the yield is ~zero
  # (`marker-unwritable` means gh is down so P7's write fails too — 03-sprint-board.md :1274
  # calls P7 best-effort; `window-invalid` runs before ISSUE is ever assigned; `container-lost`
  # names the PREVIOUS member), and the cost is real — `board_col_of` reads the CACHE, which is
  # only refreshed on a successful write, so "the last P3 write failed" leaves the card reading
  # `in_progress` and the widened gate relabels a COMPLETED member "interrupted".
  #
  # None of the halt paths needs it: they set `HALT_REASON` and leave `FINISHED` alone, so this
  # gate is open for them and the reason below is theirs. `FINISHED=1` there was redundant the
  # moment the marker's reason started coming from `HALT_REASON`.
  if [ "$FINISHED" -eq 0 ]; then
    # P7 (03-sprint-board.md §5.2). bash defers a trap while a foreground command runs, so a
    # `kill` lands AFTER the child session has already committed, pushed and opened its PR but
    # BEFORE the `case "$STATE"` arms run — P1's `In progress` would then sit there forever,
    # and the next run's queue no longer contains that Issue.
    # ⚠ THREE guards, each for a measured failure:
    #   `FINISHED -eq 0` — without it a run that completed normally but whose LAST P3 write
    #     failed would relabel that member "Guild was interrupted", which is a false statement.
    #   `${ISSUE:-}` — the empty-queue `exit 0` fires this trap before the loop ever ran.
    #   still `in_progress` — P2/P3/P4 may already have written the real outcome; the card
    #     cache is what tells us whether anything did.
    if [ -n "${ISSUE:-}" ] && [ "$(board_col_of "$ISSUE")" = "in_progress" ]; then
      board_col "$ISSUE" blocked interrupted
    fi
    # ⚠ Guarded, like heartbeat's. Without the guard a board-LESS run that gets interrupted
    # gains two keys in its marker, which is the only thing an existing user could observe
    # about this feature — and "nothing changes when the board is off" has to be literal.
    if [ "${BOARD_WAS_ON:-0}" = 1 ]; then
      ledger_set board_fails "${BOARD_FAILS:-0}" 2>/dev/null || true
      ledger_set board_bugs "${BOARD_BUGS:-0}" 2>/dev/null || true
      ledger_set board_unknown_col "${BOARD_UNKNOWN_COL:-0}" 2>/dev/null || true
    fi
    # ⚠ The reason comes from HALT_REASON, never from a literal: `sigTERM`/`sigHUP` are set by
    # `on_signal`, the three window/marker/container paths by their own exit points.
    marker_write "halted:${HALT_REASON:-interrupted}" 2>/dev/null || true
  fi
  if [ "$COMPLETED" -eq 1 ]; then
    # ⚠ The board config file goes with the script. Leaving it behind means the next run of
    # this same tracker reads a STALE board config — and if the human turned the board off in
    # `config.sprint.board` meanwhile, `run.md` step 2b writes no file, the old one survives,
    # and the supervisor projects to a board the config says is gone.
    # ⚠ The window file goes with the script and the board config, for the same reason: a file
    # left behind is read as "the window is still on" by the NEXT run of this tracker, which
    # would then sit out the day for a window the human never asked for again (§3.4).
    rm -f "$SCRIPT_PATH" "$BOARD_CONF" "$WINDOW_CONF"; echo "[sprint] Removed supervisor script"
  else
    echo "[sprint] Run did not complete — script kept at $SCRIPT_PATH"
    echo "[sprint] Re-run \`/gld sprint run\` to continue; state comes from GitHub labels."
  fi
}
# ⚠ The signal traps MUST be separate from the EXIT trap, and they MUST exit.
# `trap cleanup EXIT INT TERM` was WRONG and measured so: bash runs the handler and then
# CARRIES ON with the script, so (a) `kill` did not stop the run, (b) the loop finished and
# overwrote `halted:interrupted` with `state: finished` — a killed run reported success — and
# (c) COMPLETED reached 1, so it deleted its own re-run script. The handler below exits, which
# then fires the EXIT trap once with FINISHED still 0.
on_signal() {                     # on_signal <name> <exit-code>
  # ⚠ Set the reason BEFORE exiting. Without this every `kill` still lands as
  # `halted:interrupted` and `_handoff.md`'s enumeration of `sigTERM`/`sigHUP` is a lie —
  # on a days-long run the marker is the only place the human can read what happened.
  HALT_REASON="sig$1"
  echo "[sprint] SIG$1 — stopping. State comes from GitHub labels; re-run \`/gld sprint run\`."
  exit "$2"
}
trap 'on_signal TERM 143' TERM
trap 'on_signal HUP 129' HUP
trap cleanup EXIT
# <!-- /guild:supervisor-core:selfdelete -->

# <!-- guild:supervisor-core:emptyguard -->
# `set -u` + an EMPTY array: bash 3.2 aborts an unguarded "${ARR[@]}" expansion with
# `ARR[@]: unbound variable` — verified. Selecting nothing is legitimate (every member may
# already be done), so exit cleanly instead of dying with a confusing bash error.
if [ ${#ORDER[@]} -eq 0 ]; then
  echo "[sprint] No members to run — nothing to do."
  COMPLETED=1; FINISHED=1
  exit 0
fi
# <!-- /guild:supervisor-core:emptyguard -->

RUN_START=$(date +%s)
DONE=0; PAUSED=0; FAILED=0; INCOMPLETE=0; BLOCKED=0
# ⚠ PAUSED_ISSUES exists only for the ledger `completion` key (§4.3): a paused member is the
# one outcome a human MUST act on, there is no completion notification, and `paused: 1`
# without a number cannot be acted on days later.
FAILED_ISSUES=(); INCOMPLETE_ISSUES=(); BLOCKED_ISSUES=(); KEPT_WORKTREES=(); PAUSED_ISSUES=()
# ⚠ Parallel to KEPT_WORKTREES, same index. The single folded string cannot be split back
# safely (`): ` can occur inside git's message), and the ledger must not carry the raw text.
KEPT_WT_ISSUE=(); KEPT_WT_REASON=()
QUEUE=("${ORDER[@]}"); SEEN=""
for n in "${ORDER[@]}"; do SEEN="$SEEN #$n "; done
TOTAL=${#ORDER[@]}; PROCESSED=0

# ─────────────────────────────────────────────────────────────────────────────
# Ledger + marker (§8.5 · §8.5a) — all parsing in python, never in bash
# ─────────────────────────────────────────────────────────────────────────────

LEDGER="$D/ledger.json"
# Existence is not validity. The writes below are not atomic, so the very crash the ledger
# exists to survive (SIGKILL mid-write) is what truncates it — and then `json.load` raises on
# every marker write and the run stops before its first Issue with a one-line traceback and no
# way to recover by re-running. Validate, and start clean if unreadable: most of the ledger is
# volatile fields (§8.5) the next run re-derives from GitHub.
# ⚠ NO LONGER "the three volatile fields, every one of which is re-derivable" — that sentence
# was true before the run window and is now false in two places. `window` (the run's own
# `HH:MM-HH:MM`, never written to config.json) and `completion` (the only report a days-long run
# can leave, written just before `state: finished`) are RUN-LOCAL and NOT re-derivable, and both
# are dropped at run start on purpose (below). 02-sprint.md §8.5's "checkpoint — three items"
# needs the same correction.
# ⚠ Except the board counters (`board_fails` · `board_bugs` · `board_account_mismatch` ·
# `board_disabled_after`): those are RUN-LOCAL and are NOT re-derivable — a fresh ledger resets
# them to zero, which reads as "the board was fine". Accepted, because the alternative is
# refusing to run over an unreadable ledger; but do not cite re-derivation as the reason.
if [ -f "$LEDGER" ]; then
  "$PY" -c 'import json,sys; json.load(open(sys.argv[1]))' "$LEDGER" 2>/dev/null \
    || { echo "[sprint] NOTE: ledger was unreadable — starting a fresh one (board counters reset to 0)"
         printf '{}' > "$LEDGER"; }
else
  printf '{}' > "$LEDGER"
fi

# ⚠ DROP THE BOARD KEYS AT RUN START. They are run-LOCAL facts living in a CROSS-RUN file, and
# `$D` survives precisely when the run ended badly (`$D` is removed only when
# FAILED+INCOMPLETE+BLOCKED == 0) — which is exactly when the human fixes the cause and re-runs.
# Without this, run 2 inherits run 1's `board_disabled_after` and `board_account_mismatch`, and
# `marker_write` renders the WHOLE ledger, so a run that projected every card correctly reports
# "연속 실패로 투영을 중단했습니다 · 계정 불일치" — and `daily` checks `board_disabled_after`
# FIRST, so that is the line the human reads. `heartbeat` re-establishes the two that still
# apply within seconds; the other two must be re-earned.
"$PY" - "$LEDGER" <<'PY' 2>/dev/null || true
import json, os, sys
path = sys.argv[1]
try:
    with open(path) as fh:
        led = json.load(fh)
except Exception:
    raise SystemExit(0)
# ⚠ `completion` and `window` are dropped for the SAME reason as the board keys, and it is
# not a nicety: `$D` survives exactly when the previous run ended badly, and `marker_write`
# renders the WHOLE ledger — so run 2's very first `heartbeat "running"` would re-publish run
# 1's worktree list, cost and window. `completion` is ONE object key on purpose: conditional
# sub-keys would simply not be written by run 2 and run 1's values would live on (§4.3).
for k in ("board_fails", "board_bugs", "board_account_mismatch",
          "board_disabled_after", "board_last_write", "board_reason_disabled",
          "board_unknown_col", "board_off_reason",
          "completion", "window"):
    led.pop(k, None)
tmp = path + ".tmp"
with open(tmp, "w") as fh:
    json.dump(led, fh, sort_keys=True)
os.replace(tmp, path)
PY

# marker_write <state>  — in-place replace of the run marker on the tracking Issue.
# ONE --paginate query returns id AND body together. `_bash_rules.md:87`: needing both and
# paginating only one lookup "is worse than paginating neither" — the body read finds the
# record while the id read comes back empty and the "empty -> create" branch posts a
# duplicate. Fetching both in one call removes the failure mode rather than managing it.
marker_write() {
  local state="$1"
  gh api "repos/$OWNER_REPO/issues/$TRACKER/comments" --paginate \
    --jq '[.[] | select((.body // "") | contains("<!-- guild:sprint:run -->")) | {id, body}]' \
    > "$D/marker.json" 2>"$D/marker.err" || { echo "[sprint] WARN: marker fetch failed"; return 1; }
  # ⚠ The exit-code handling MUST NOT be a brace group on this line. A `|| { … }` whose
  # closing `}` sits on the next line gets swallowed as the FIRST LINE OF THE HEREDOC BODY,
  # leaving the group open forever — `bash -n` then reports "unexpected end of file" at the
  # end of the file, hundreds of lines away. `|| MRC=$?` completes on this line, so it is safe.
  MRC=0
  "$PY" - "$D" "$LEDGER" "$state" "$HOSTNAME_S" "$$" "$RUN_START" <<'PY' > "$D/marker.out" 2>"$D/marker.err2" || MRC=$?
import datetime, json, os, sys
d, ledger_path, state, host, pid, started = sys.argv[1:7]
OPEN, CLOSE = "<!-- guild:sprint:run -->", "<!-- /guild:sprint:run -->"
with open(ledger_path) as fh:
    led = json.load(fh)
led.update({
    "host": host, "pid": int(pid), "state": state,
    # Not utcfromtimestamp/utcnow — both are deprecated in 3.12+ and emit a DeprecationWarning
    # on stderr. A marker write that fails three times STOPS the run (heartbeat's guard), so the
    # day they are removed this would halt every sprint at its first issue.
    "started": datetime.datetime.fromtimestamp(int(started), datetime.timezone.utc)
                                .strftime("%Y-%m-%dT%H:%M:%SZ"),
    "heartbeat": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
})
with open(ledger_path, "w") as fh:
    json.dump(led, fh, sort_keys=True)
block = "%s\n```json\n%s\n```\n%s" % (OPEN, json.dumps(led, sort_keys=True), CLOSE)
found = json.load(open(os.path.join(d, "marker.json")))
# Several matches: use the OLDEST (lowest id) as the record of account and warn. The
# nearest precedent is _handoff.md Section B's auditor-violation rule, which judges "resolved"
# by POSITION rather than presence. ⚠ Not the same concept — that rule is about a line's place
# INSIDE one comment body, this one about id order ACROSS comments. Here the oldest is the
# one every earlier run has been updating, so switching to a newer one would orphan history.
if len(found) > 1:
    print("MULTI %d" % len(found), file=sys.stderr)
target = min(found, key=lambda c: c["id"]) if found else None
if target is None:
    print("CREATE"); print(block, file=open(os.path.join(d, "body.md"), "w"))
else:
    body = target["body"] or ""
    if OPEN in body and CLOSE in body:
        head, rest = body.split(OPEN, 1)
        _, tail = rest.split(CLOSE, 1)
        new = head + block + tail
    else:
        new = (body.rstrip() + "\n\n" + block) if body.strip() else block
    print("PATCH %d" % target["id"])
    open(os.path.join(d, "body.md"), "w").write(new)
PY
  if [ "$MRC" -ne 0 ]; then
    echo "[sprint] WARN: marker render failed ($(head -1 "$D/marker.err2" 2>/dev/null || true))"
    return 1
  fi
  local action id
  action="$(head -1 "$D/marker.out" 2>/dev/null || true)"
  case "$action" in
    CREATE)
      gh issue comment "$TRACKER" --repo "$OWNER_REPO" --body-file "$D/body.md" >/dev/null 2>&1 \
        || { echo "[sprint] WARN: marker create failed"; return 1; } ;;
    PATCH*)
      id="${action#PATCH }"
      gh api "repos/$OWNER_REPO/issues/comments/$id" -X PATCH --field body=@"$D/body.md" >/dev/null 2>&1 \
        || { echo "[sprint] WARN: marker patch failed"; return 1; } ;;
    *) echo "[sprint] WARN: marker render produced no action"; return 1 ;;
  esac
  return 0
}

# A marker failure must never kill the run — but §8.2's duplicate-run guard depends on it,
# so three consecutive failures stop cleanly instead of running blind.
MARKER_FAILS=0
# ⚠ A VARIABLE, not the literal 3 it used to be, and `wait_for_window` raises it to 18 for the
# duration of the wait. Why 18 is not "inconsistent with 3" — do not revert this for tidiness:
#   • 3 consecutive failures normally span HOURS of real work, so a transient outage recovers
#     in between. While waiting for the window the heartbeat is the ONLY thing that runs and
#     the only thing that can kill the run: 10 min x 3 means a 30-minute network drop kills a
#     multi-night run at 03:00.
#   • the kill-switch's own justification (the duplicate-run guard, just above) is weak here:
#     that guard judges by `host` + a LIVE pid + cmdline, never by heartbeat freshness.
# 18 x ~10 min is roughly three hours. It absorbs outages that RECOVER; it cannot absorb a
# permanently expired `GH_TOKEN`, which is why that is a Phase 0 question in run.md (§4.2).
MARKER_MAX=3
heartbeat() {
  # Board counters ride along here (03-sprint-board.md §7.2). This is the only position that
  # satisfies all three requirements at once: the human sees them WHILE the run is going
  # (`daily` reads this marker), whatever the last heartbeat wrote SURVIVES a TERM/`exit 1`/
  # crash, and the empty-queue `exit 0` never reaches here so it cannot touch counters that
  # are not initialised yet. `cleanup`-only loses the first, final-marker-only loses the second.
  # ⚠ `ledger_set` is defined below this function; both are only ever CALLED from the loop.
  # ⚠ `BOARD_WAS_ON`, not `BOARD_NUMBER`. `board_breaker` empties BOARD_NUMBER to stop paying
  # for a dead board, and guarding on the live value meant the breaker HID the very counters it
  # had just finished counting: `board_bugs` was lost outright and `board_fails` came out
  # ABSENT, which selects `daily`'s reassuring row ("0 or absent → 마지막 투영 …").
  if [ "$BOARD_WAS_ON" = 1 ]; then
    ledger_set board_fails "$BOARD_FAILS" 2>/dev/null || true
    ledger_set board_bugs "$BOARD_BUGS" 2>/dev/null || true
    ledger_set board_unknown_col "$BOARD_UNKNOWN_COL" 2>/dev/null || true
  fi
  if marker_write "$1"; then
    MARKER_FAILS=0
  else
    MARKER_FAILS=$((MARKER_FAILS + 1))
    if [ "$MARKER_FAILS" -ge "$MARKER_MAX" ]; then
      HALT_REASON="marker-unwritable"
      echo "[sprint] Marker unwritable ${MARKER_MAX}x — stopping so the duplicate-run guard stays honest."
      # ⚠ `FINISHED` is NOT set — `cleanup` writes `halted:$HALT_REASON` and P7 still gets a
      # chance at the card, which is the pre-window behaviour for this path.
      # ⚠ THE LEDGER FIRST, and it is not belt-and-braces. `marker_write`'s FIRST action is a
      # `gh api` read of the existing comment, and it `return 1`s there — BEFORE the python that
      # updates the ledger. N consecutive failures IS "the marker cannot be written", so the
      # call below fails too and the reason would exist nowhere. `ledger_set` is a local file
      # write with no gh in it, and `$D` survives (a halt has COMPLETED=0), so the human reads
      # the reason out of `ledger.json` in the morning.
      ledger_set state '"halted:marker-unwritable"' 2>/dev/null || true
      # ⚠ No marker_write here. `cleanup` attempts `halted:$HALT_REASON` on the way out, and a
      # second attempt from inside the function that just failed three times adds nothing.
      exit 1
    fi
  fi
}

ledger_set() {   # ledger_set <dotted.key> <json-value>
  "$PY" - "$LEDGER" "$1" "$2" <<'PY'
import json, os, sys
path, key, raw = sys.argv[1], sys.argv[2], sys.argv[3]
with open(path) as fh:
    led = json.load(fh)
try:
    val = json.loads(raw)
except ValueError:
    val = raw
node, parts = led, key.split(".")
for p in parts[:-1]:
    node = node.setdefault(p, {})
node[parts[-1]] = val
# Write-then-rename: a SIGKILL between truncate and write is exactly the crash this file has
# to survive, and an in-place `open(path,"w")` loses the whole ledger to it.
tmp = path + ".tmp"
with open(tmp, "w") as fh:
    json.dump(led, fh, sort_keys=True)
os.replace(tmp, path)
PY
}

ledger_get() {   # ledger_get <dotted.key> <default>
  "$PY" - "$LEDGER" "$1" "$2" <<'PY'
import json, sys
path, key, default = sys.argv[1], sys.argv[2], sys.argv[3]
try:
    with open(path) as fh:
        node = json.load(fh)
except Exception:
    print(default); raise SystemExit(0)
for p in key.split("."):
    if not isinstance(node, dict) or p not in node:
        print(default); raise SystemExit(0)
    node = node[p]
print(node if not isinstance(node, (dict, list)) else __import__("json").dumps(node))
PY
}

# ─────────────────────────────────────────────────────────────────────────────
# §8.5a — the failure taxonomy, written where a LATER session can read it
# ─────────────────────────────────────────────────────────────────────────────
# The supervisor's stdout goes to the buffer of whatever launched it. `daily` is a separate,
# later session and cannot read that buffer — so a failure class that exists only in an `echo`
# cannot answer D8's "why did this Issue fail". One JSON object per line, appended, never
# rewritten, in the human's checkout so it survives worktree and container teardown.
EVENTS="$RUNDIR/failures.jsonl"
# record_event — append one line and nothing more. A BLOCK is an event, not a failure: the
# dependency simply has not landed, and `retro` has to count blocks (§10.1) while `daily`
# must not render them as failures.
# ⚠ ONE python call writes BOTH files, and it reports if either failed. They used to be two
# independent `|| true` writes, which is harmful in both directions: if only the jsonl failed the
# DAG blocked the dependants with NO recorded reason (`daily` shows `dep-failed:#N` and "이유 기록
# 없음"), and if only failed.txt failed the log showed a failure while the dependants stacked onto
# the broken work — the exact outcome record_failure exists to prevent.
#
# `datetime.now(timezone.utc)`, not `utcnow()`: the latter is deprecated in 3.12+ and its
# DeprecationWarning goes to stderr, which this function does not redirect — so the warning
# leaked into the supervisor's output, and on the day it is removed the `|| true` would swallow
# the failure silently. `marker_write` uses the same API and would abort the run at 3 strikes.
_record() {   # _record <issue> <class> <detail> <failed-path-or-empty>
  RRC=0
  "$PY" - "$EVENTS" "$TRACKER" "$TIMESTAMP" "$1" "$2" "$3" "${4:-}" <<'PY' || RRC=$?
import datetime, json, sys
out, tracker, run, issue, cls, detail, failed = (sys.argv[1:8] + [""])[:7]
stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
row = json.dumps({"at": stamp, "tracker": int(tracker), "run": run, "issue": int(issue),
                  "class": cls, "detail": detail[:200]}, sort_keys=True)
with open(out, "a") as fh:
    fh.write(row + "\n")
if failed:
    with open(failed, "a") as fh:
        fh.write("%d\n" % int(issue))
PY
  if [ "$RRC" -ne 0 ]; then
    # ⚠ >&2, and this is not cosmetic. `record_event` is called from INSIDE worktree_acquire,
    # whose STDOUT IS ITS RETURN VALUE — a warning on stdout became part of $WT, link_memory
    # created that bogus path, `cd` succeeded, and the child ran in a directory that is not a
    # git repo while the run reported `Done: 1 / Failed: 0` and deleted its own script
    # (measured). The same failure this file documents at worktree_acquire, re-introduced by a
    # later edit and caught only by running it.
    echo "[sprint] WARN: could not record #$1 as $2 — the reason and/or the terminal marker are missing" >&2
  fi
  return 0
}

record_event()   { _record "$1" "$2" "$3" ""; }

# record_failure — the event PLUS the terminal marker the DAG needs.
# §8.7: without `terminal[issue] = "failed"` the dependents of a failed Issue are NOT blocked,
# and because the spine usually left a branch behind, `--mode base` hands that branch back and
# the next PR stacks on top of broken work.
record_failure() { _record "$1" "$2" "$3" "$D/failed.txt"; }

# children_pending <parent> — how many of this parent's children are NOT yet guild:done.
# Used as the progress signal for a mid-orchestration split. Prints a number, always.
# ⚠ Prints a NUMBER or `-1`, never an empty string. `|| echo 0` only covers a non-zero exit;
# `gh` returning exit 0 with EMPTY stdout produced "" — and "" then made `[ "$X" -lt … ]` abort
# with `integer expression expected` while the caller read it as "first pass" forever. Measured:
# 79 child sessions spawned in 25 seconds with no ceiling. `-1` means "unknown", which the
# caller must treat as NO progress — never as a fresh start.
children_pending() {
  local n
  n="$(gh issue list --repo "$OWNER_REPO" --label guild:child --state all --limit 200 \
    --json number,body,labels \
    --jq "[.[] | select((.body // \"\") | test(\"Parent Issue: #${1}([^0-9]|\$)\")) | select((.labels // []) | map(.name) | index(\"guild:done\") | not)] | length" \
    2>/dev/null)" || n=""
  case "$n" in
    ''|*[!0-9]*) printf '%s' "-1" ;;
    *)           printf '%s' "$n" ;;
  esac
}

# hb_sleep <seconds> — sleep in chunks, refreshing the heartbeat each chunk.
# ⚠ This is why the rate-limit VERBATIM core below stops before the sleep. §8.2 requires a
# heartbeat at least every 10 minutes "including inside the wait loop", and a rate-limit wait
# was measured at ~115 minutes. A single `sleep "$WAIT"` (what batch does) would leave the
# marker stale for two hours and the duplicate-run guard would read a live run as crashed.
hb_sleep() {
  # A non-numeric or negative argument would make the arithmetic below either abort under
  # `set -e` or loop on a nonsense value. Callers clamp, but this is the last line of defence.
  case "$1" in ''|*[!0-9]*) return 0 ;; esac
  local remain="$1" chunk
  while [ "$remain" -gt 0 ]; do
    chunk="$HEARTBEAT_EVERY"
    [ "$remain" -lt "$chunk" ] && chunk="$remain"
    sleep "$chunk"
    remain=$((remain - chunk))
    heartbeat "rate-limited-remaining-${remain}s"
  done
}

# ─────────────────────────────────────────────────────────────────────────────
# §8.4c — assemble sprint_dag.py input from gh output + the immutable member table
# ─────────────────────────────────────────────────────────────────────────────
# Redirection is used freely here: `_bash_rules.md:85` puts a generated script's own contents
# outside those rules. That is what makes this plumbing possible at all — the design's
# `--input <path>` interface has no shell-side producer otherwise.

refresh_dag_input() {
  gh pr list --repo "$OWNER_REPO" --state all --limit 200 \
    --json number,headRefName,baseRefName,state,mergedAt,reviewDecision,closingIssuesReferences \
    > "$D/prs.json" 2>/dev/null || printf '[]' > "$D/prs.json"
  gh issue list --repo "$OWNER_REPO" --state all --limit 200 --json number,labels \
    > "$D/labels.json" 2>/dev/null || printf '[]' > "$D/labels.json"
  git -C "$SUP" branch --format='%(refname:short)' > "$D/branches.txt" 2>/dev/null || : > "$D/branches.txt"
  [ -f "$D/failed.txt" ] || : > "$D/failed.txt"
  "$PY" - "$D" "$DEFAULT_BRANCH" <<'PY' || return 1
import json, os, sys
d, default_branch = sys.argv[1], sys.argv[2]
members = json.load(open(os.path.join(d, "members.json")))     # written once by run.md
prs_raw = json.load(open(os.path.join(d, "prs.json")))
labels_raw = json.load(open(os.path.join(d, "labels.json")))
branches = [l.strip() for l in open(os.path.join(d, "branches.txt")) if l.strip()]

member_nums = set(int(m["number"]) for m in members)

# issue -> PR. `closingIssuesReferences` is the primary link (Step 5 puts `Closes #<N>` in
# the body). It can come back empty — the design does not assume otherwise — so fall back to
# an issue-number token in the head branch name. sprint_dag.py refuses to guess when that
# token matches more than one branch.
prs = []
for pr in prs_raw:
    state = "MERGED" if pr.get("mergedAt") else str(pr.get("state", "")).upper()
    if state not in ("MERGED", "OPEN", "CLOSED"):
        continue
    issues = [int(r["number"]) for r in (pr.get("closingIssuesReferences") or [])]
    if not issues:
        head = pr.get("headRefName") or ""
        issues = [n for n in member_nums
                  if __import__("re").search(r"(?<!\d)%d(?!\d)" % n, head)]
        if len(issues) != 1:
            continue
    for n in issues:
        if n in member_nums:
            prs.append({"issue": n, "branch": pr.get("headRefName"), "state": state})

# label -> terminal state, using the same precedence as the `case` arms below.
terminal = {}
for it in labels_raw:
    n = int(it["number"])
    if n not in member_nums:
        continue
    names = [l["name"] for l in (it.get("labels") or [])]
    if "guild:needs-human" in names:
        terminal[str(n)] = "needs-human"
    elif "guild:done" in names:
        terminal[str(n)] = "done"
    elif "guild:children" in names:
        terminal[str(n)] = "children"

# `failed` has no label to derive it from — a failed Issue keeps whatever stage label it
# reached — so it comes from what THIS run recorded. It must not override a terminal label:
# an Issue that failed on an earlier attempt and later reached guild:done is done.
#
# ⚠ A MERGED PR outranks the record too, and the labels alone do NOT cover that case: a stacked
# PR merges into its dependency's branch, which fires no closing keyword, so the Issue keeps no
# `guild:done` and stays open. Without this the strongest possible evidence of success — the
# work is IN — loses to a stale line in failed.txt, and `--mode blocked` reports
# `dep-failed:#N` while `--mode base` answers DEFAULT for the same node. failed.txt accumulates
# for as long as $D survives, so that contradiction outlives the attempt that caused it.
merged = set(p["issue"] for p in prs if p.get("state") == "MERGED")
for line in open(os.path.join(d, "failed.txt")):
    line = line.strip()
    if not line.isdigit():
        continue
    n = int(line)
    if n in member_nums and str(n) not in terminal and n not in merged:
        terminal[str(n)] = "failed"

json.dump({"members": members, "prs": prs, "terminal": terminal,
           "branches": branches, "default_branch": default_branch},
          open(os.path.join(d, "run.json"), "w"), sort_keys=True)
PY
}

# ─────────────────────────────────────────────────────────────────────────────
# §8.4b — base refresh. remote-tracking namespace ONLY.
# ─────────────────────────────────────────────────────────────────────────────
# `git fetch origin <b>:<b>` is refused whenever <b> is checked out in ANY worktree — and the
# human's checkout holds it, by premise. Fetching into refs/remotes/ never collides, and the
# human's local branch is not touched (measured). The supervisor worktree is --detach for the
# same reason: it cannot check out a branch the human already has.
# `git worktree prune` is REPO-GLOBAL: it drops the registration of ANY worktree whose
# directory is currently absent, including one of the human's that is merely on an unmounted
# volume or temporarily moved (measured — the directory survives on disk and becomes an
# orphan). §12.5-7 promises the human's checkout is not disturbed, so prune only when every
# prunable entry is inside our own container.
prune_safe() {
  git -C "$HUMAN_REPO" worktree list --porcelain 2>/dev/null > "$D/wtlist.txt" || return 0
  local p="" foreign=0 line
  while IFS= read -r line; do
    case "$line" in
      "worktree "*) p="${line#worktree }" ;;
      prunable*)    case "$p" in "$CONTAINER"/*) ;; *) foreign=1 ;; esac ;;
    esac
  done < "$D/wtlist.txt"
  if [ "$foreign" -eq 1 ]; then
    echo "[sprint] NOTE: skipped \`worktree prune\` — a worktree outside $CONTAINER is prunable and pruning is repo-global"
    return 0
  fi
  git -C "$HUMAN_REPO" worktree prune 2>/dev/null || true
}

refresh_base() {
  git -C "$SUP" fetch --quiet origin \
    "$DEFAULT_BRANCH:refs/remotes/origin/$DEFAULT_BRANCH" 2>"$D/fetch.err" && return 0
  echo "[sprint] WARN: base refresh failed — $(head -1 "$D/fetch.err" 2>/dev/null || true)"
  return 1
}

# ─────────────────────────────────────────────────────────────────────────────
# §8.1c — worktree acquisition, four states. NEVER --force, NEVER -b.
# ─────────────────────────────────────────────────────────────────────────────
# -b is omitted because branch naming belongs to the spine (_execute_spine.md Step 0): the
# name is derived from conventions.md and is not reproducible across sessions, and a
# supervisor-made branch makes Step 0 misclassify every fresh Issue as a resume.
worktree_path() { printf '%s/issue-%s' "$CONTAINER" "$1"; }

worktree_acquire() {
  local issue="$1" wt base branch
  wt="$(worktree_path "$issue")"
  base="$2"

  # Registered but the directory is gone → prune, then treat as absent. Also runs at start of
  # the loop, not only at run end: a $TMPDIR fallback container can be cleaned mid-run.
  if git -C "$SUP" worktree list --porcelain 2>/dev/null | grep -qxF "worktree $wt"; then
    if [ -d "$wt" ]; then
      # ⚠ >&2. This function's STDOUT IS ITS RETURN VALUE (`WT="$(worktree_acquire …)"`), so a
      # progress line on stdout becomes part of the path — and link_memory's `mkdir -p` then
      # CREATES that bogus path, so `cd` succeeds and the child runs in a directory that is
      # not a git repo and has no dependencies. Measured; it does not surface as an error.
      echo "  ↺ reusing worktree $wt" >&2
      printf '%s' "$wt"; return 0
    fi
    # ⚠ prune_safe, not a bare prune. `$SUP` shares the ref store with the human's checkout,
    # so `git -C "$SUP" worktree prune` is the SAME repo-global operation — it would drop the
    # registration of a worktree of theirs that is merely on an unmounted volume.
    prune_safe
  fi

  # A path that exists but is not a registered worktree is NOT reusable — `git worktree add`
  # refuses with "already exists" and cd'ing into it makes every git call fail.
  if [ -e "$wt" ]; then
    echo "  ✗ $wt exists but is not a registered worktree — resolve by hand" >&2
    return 1
  fi

  # An existing branch for this issue: check it OUT (no -b, no --detach). --detach would leave
  # the branch as "not the current branch", and a legitimate resume branch usually has an EMPTY
  # log (the developer commits only at the end) — that combination is exactly what
  # _execute_spine.md Step 0 (a) DROPS, sending a resumable Issue down the fresh path where
  # `git switch -c` then dies with "already exists" and the Issue pauses.
  # ⚠ NEVER guess. `git -C "$SUP" branch` lists the SHARED ref store, so it includes the
  # human's own branches — a scratch branch like `chore/101-notes` matches #101 just as well as
  # `feature/#101-the-real-one`, and `head -1` picks by refname alphabetical order, which has
  # nothing to do with correctness (measured: it checked out the scratch branch and ran the
  # developer on top of it). More than one match is exactly the case sprint_dag.py answers with
  # BLOCKED:dep-branch-ambiguous, and the same rule applies here. The substring hazard
  # (#1011 vs #101) is already excluded by the regex; the real hazard is an equal-count match.
  git -C "$SUP" branch --format='%(refname:short)' 2>/dev/null \
    | grep -E "(^|[^0-9])$issue([^0-9]|$)" > "$D/cand.txt" 2>/dev/null || : > "$D/cand.txt"
  local ncand
  ncand="$(grep -c . "$D/cand.txt" 2>/dev/null)" || ncand=0
  if [ "$ncand" -gt 1 ]; then
    # ⚠ Write the reason to $D/wt.err. The caller reports `head -1 "$D/wt.err"`, so returning
    # without writing it made this refusal borrow the PREVIOUS issue's error message — the
    # human was told to fix something unrelated (measured).
    printf '#%s has %s candidate branches — choosing one would be a guess:\n' \
      "$issue" "$ncand" > "$D/wt.err"
    sed 's/^/      /' "$D/cand.txt" >> "$D/wt.err"
    echo "  ⊘ #$issue has $ncand candidate branches — not guessing" >&2
    sed 's/^/      /' "$D/cand.txt" >&2
    return 2                       # 2 = ambiguous (a BLOCK), 1 = failed
  fi
  branch="$(head -1 "$D/cand.txt" 2>/dev/null || true)"
  # ⚠ ONE match is still an assumption. This lists the SHARED ref store, so a scratch branch of
  # the human's that merely carries the issue number (`chore/101-notes`) is an equally good
  # match — and it was silently checked out and developed on, with the dependants' PRs stacked
  # on top of it (measured). The supervisor cannot prove ownership: branch naming comes from the
  # repo's conventions and is not reproducible across sessions (that is why it never names one).
  # So say so, every time, and record it — an assumption a human can see is not a silent one.
  if [ -n "$branch" ]; then
    echo "  ⓘ #$issue resuming on the only branch that matches: $branch" >&2
    record_event "$issue" branch-assumed "resumed on $branch (single token match; ownership not provable)"
  fi
  if [ -n "$branch" ]; then
    # `>/dev/null` for the same reason: `git worktree add` prints "HEAD is now at <sha> <subj>"
    # on STDOUT (measured — it survives `2>/dev/null`), and only stderr is captured here.
    if git -C "$SUP" worktree add "$wt" "$branch" >/dev/null 2>"$D/wt.err"; then
      echo "  ↺ resumed worktree $wt on $branch" >&2
      printf '%s' "$wt"; return 0
    fi
    # Refusal here is CORRECT and informative: the branch is held by another worktree — most
    # often a preserved worktree from an earlier sprint (its container is keyed by tracker).
    echo "  ✗ cannot check out $branch — $(head -1 "$D/wt.err")" >&2
    return 1
  fi

  if git -C "$SUP" worktree add --detach "$wt" "$base" >/dev/null 2>"$D/wt.err"; then
    printf '%s' "$wt"; return 0
  fi
  echo "  ✗ worktree add failed — $(head -1 "$D/wt.err")" >&2
  return 1
}

# Link the gitignored memory dir to the human's, so growth signals survive worktree removal.
# capture_signal.py resolves the repo root by walking up for a `.git` ENTRY — a worktree's
# `.git` is a file, which it matches — so without this the signals land inside the worktree
# and `git worktree remove` deletes them silently (exit 0, measured): the evolve that `retro`
# calls then sees zero signals and declines, and an entire unattended sprint grows nothing.
link_memory() {
  local wt="$1"
  mkdir -p "$HUMAN_REPO/.claude/guild/memory"
  [ -e "$wt/.claude/guild/memory" ] && return 0
  mkdir -p "$wt/.claude/guild"
  ln -s "$HUMAN_REPO/.claude/guild/memory" "$wt/.claude/guild/memory" 2>/dev/null || true
}

# Remove only at guild:done, and never with --force. git's own refusal is the whole safety
# mechanism: a clean tree is removable (branch and commits survive in the shared .git), a
# dirty one is refused and preserved. NOTE a refusal does NOT always mean unfinished work —
# _execute_spine.md Step 3.5b leaves a tech-writer's ADR untracked by design, so `daily` reports
# source-vs-docs separately rather than judging.
worktree_release() {
  local issue="$1" wt
  wt="$(worktree_path "$issue")"
  [ -d "$wt" ] || return 0
  if git -C "$SUP" worktree remove "$wt" 2>"$D/rm.err"; then
    return 0
  fi
  # ⚠ TWO shapes on purpose. The human-facing string keeps git's own words; the parallel
  # arrays carry what the ledger may publish. `$D/rm.err` reads
  # `fatal: '<ABSOLUTE PATH>' contains modified or untracked files…` — the reason string itself
  # holds an absolute path, so `completion.kept_worktrees` gets a CLASSIFICATION instead
  # (04-sprint-window.md §4.3 · INV5). The classes differ in what the human has to do, which is
  # the only thing the field was ever for.
  _rmerr="$(head -1 "$D/rm.err")"
  case "$_rmerr" in
    *"is locked"*|*"locked working tree"*) _rmclass="locked" ;;
    *"modified or untracked"*)             _rmclass="dirty" ;;
    *"is a main working tree"*)            _rmclass="main-worktree" ;;
    *)                                     _rmclass="other" ;;
  esac
  KEPT_WORKTREES+=("#$issue ($wt): $_rmerr")
  KEPT_WT_ISSUE+=("#$issue")
  KEPT_WT_REASON+=("$_rmclass")
  echo "  ⓘ worktree kept for #$issue — $(head -1 "$D/rm.err")"
  return 0
}

# <!-- guild:supervisor-core:window -->
# The run window (04-sprint-window.md §1.2 · §1.3 · §2.1). Reading and validating only — the
# ONE place that waits is the queue loop below, in front of the pop.
#
# ⚠ POSITION IS LOAD-BEARING and §3.1 fixes it: immediately above the `# Main loop` divider.
#   • after `EVENTS=` — a test harness cuts the file at `^EVENTS=` to source the helpers, and
#     `window_fail`'s `exit 1` would kill that harness instead of the run.
#   • after `ledger_set`'s definition — `heartbeat` calls `ledger_set` when the board is on;
#     above it bash returns 127 and `2>/dev/null || true` eats it (that is how D11 died).
#   • below the selfdelete fence — three harnesses cut there.
#   • inside the `# Main loop` cut — the arithmetic checks source this region.
# ⚠ Do not quote the fence comment above/below anywhere else in this file: a test counts
#   occurrences file-wide with `grep -c`, so a mention alone unbalances the pair check.

window_fail() {                        # window_fail <message>
  echo "FAIL: $1" >&2
  # ⚠ `HALT_REASON` **and** a marker write here, but NOT `FINISHED=1` (04-sprint-window.md
  # §4.2b). The reason:
  #   - Writing the marker here makes the reason durable at the earliest point — this runs before
  #     `heartbeat "running"`, so it may be the run's first marker, and the human's only clue
  #     that a typo (not a crash) stopped the night.
  #   - `cleanup` then writes `halted:$HALT_REASON` again on the way out. Same string, so the
  #     repeat is idempotent — one extra PATCH on a path that is aborting anyway.
  #   - `FINISHED=1` would have suppressed that second write, but it also closes the gate that
  #     P7 and the counter flush share, and `board_col_of` reads a CACHE that a failed write
  #     leaves saying `in_progress` — so a completed member could be relabelled "interrupted".
  #     Nothing here needs protecting: ISSUE is unassigned, so P7 short-circuits on `${ISSUE:-}`.
  # ⚠ COMPLETED stays 0 — at 1 the script deletes itself, and a run refused for a typo is
  # exactly the run the human has to fix and start again.
  HALT_REASON="window-invalid"
  marker_write "halted:window-invalid" 2>/dev/null || true
  exit 1
}

# in_window — true when the wall clock is inside the window. No window => always true.
in_window() {
  # ⚠ `if`, not `[ -z … ] && return 0`. The `&&` form is safe in the middle of a function and
  # FATAL as its last statement under `set -e`; this one is one refactor away from being last.
  if [ -z "${WIN_START:-}" ]; then return 0; fi
  local now
  # ⚠ `10#`. `$(( 0830 ))` is `value too great for base` — bash reads a leading zero as octal —
  # and under `set -e` that kills the whole run. The wait loop CROSSES 08:00-09:59 every single
  # night, so without this the failure is not a probability, it is a nightly certainty, timed
  # for the minutes before the window opens (measured, §7 A/B).
  now=$(( 10#$(date +%H%M) ))
  if [ "$WIN_START" -lt "$WIN_END" ]; then
    [ "$now" -ge "$WIN_START" ] && [ "$now" -lt "$WIN_END" ]
  else
    # crosses midnight
    [ "$now" -ge "$WIN_START" ] || [ "$now" -lt "$WIN_END" ]
  fi
}

if [ -f "$WINDOW_CONF" ]; then
  # ⚠ Each guard gets its OWN message fragment. With one shared message the unreadable-file
  # guard is undefended: remove it and `WFOUND=0` makes the next guard produce a byte-identical
  # outcome (§3.2).
  if [ ! -r "$WINDOW_CONF" ]; then
    window_fail "window config is unreadable: $WINDOW_CONF"
  fi
  WFOUND=0
  # First-`=`-only split, reusing the `.board` parser's shape.
  while IFS='=' read -r wk wv || [ -n "$wk" ]; do
    wk="$(printf '%s' "${wk%$'\r'}" | tr -d '[:space:]')"
    case "$wk" in
      # ⚠ The VALUE is stripped of whitespace too — unlike `.board`, which preserves display
      # names byte-for-byte on purpose. Whitespace carries no meaning in a clock time, and
      # without this `window= 22:00-10:00` written by an LLM refuses to start the run.
      window) WIN_RAW="$(printf '%s' "${wv%$'\r'}" | tr -d '[:space:]')"; WFOUND=1 ;;
    esac
  done < "$WINDOW_CONF"
  if [ "$WFOUND" -eq 0 ]; then
    window_fail "window config has no \`window=\` line: $WINDOW_CONF"
  fi

  WIN_RAW="$(printf '%s' "$WIN_RAW" | tr '~' '-')"     # second lock; run.md normalises first
  case "$WIN_RAW" in
    none|'')
      # ⚠ Accepted, not an error. run.md removes the file when there is no window, so
      # `window=none` reaching here is an LLM slip whose INTENT is unambiguous. A malformed
      # time is something we do not understand; `none` is something we do.
      WIN_RAW=""
      ;;
    [0-9][0-9]:[0-9][0-9]-[0-9][0-9]:[0-9][0-9])
      # ⚠ `10#` only AFTER the shape check. Arithmetic first and `29:99` dies in `$(( ))`
      # before any guard runs — `set -e`, no HALT_REASON, marker reads `halted:interrupted`.
      WSH="${WIN_RAW%%:*}"; WREST="${WIN_RAW#*:}"
      WSM="${WREST%%-*}";   WREST="${WREST#*-}"
      WEH="${WREST%%:*}";   WEM="${WREST##*:}"
      if [ "$(( 10#$WSH ))" -gt 23 ] || [ "$(( 10#$WEH ))" -gt 23 ] \
         || [ "$(( 10#$WSM ))" -gt 59 ] || [ "$(( 10#$WEM ))" -gt 59 ]; then
        window_fail "window field out of range: $WIN_RAW (HH 00-23, MM 00-59)"
      fi
      WIN_START=$(( 10#$WSH * 100 + 10#$WSM ))
      WIN_END=$((   10#$WEH * 100 + 10#$WEM ))
      # ⚠ start == end is REFUSED, and that refusal is what makes §2.4's termination proof
      # true: with start != end the window is guaranteed to open within 24 hours.
      if [ "$WIN_START" -eq "$WIN_END" ]; then
        window_fail "window start equals end ($WIN_RAW) — omit the window instead"
      fi
      # ⚠ Zero-padded, because WIN_START is an INTEGER: 09:00 is 900, and an unpadded token
      # (`waiting-for-window-900`) is a shape five readers do not have.
      WIN_TOKEN="$(printf '%04d' "$WIN_START")"
      ;;
    *)
      # ⚠ The default direction of a parse failure is ALWAYS "do not run". A constraint we
      # could not read is not an absent constraint, it is one we do not know.
      window_fail "--window must be HH:MM-HH:MM (24h, zero-padded), e.g. 22:00-10:00"
      ;;
  esac
fi

WAIT_CHUNK=60               # ⚠ NOT HEARTBEAT_EVERY (600). See below.
WAIT_MARKER_MAX=18          # consecutive marker failures tolerated while waiting (§2.2)

# wait_for_window — the ONE wait point. Called in front of the queue pop.
wait_for_window() {
  if [ -z "${WIN_START:-}" ]; then return 0; fi
  if in_window; then return 0; fi
  echo "[sprint] Outside the run window ($WIN_RAW) — waiting. Stop with: kill $$"
  # ⚠ These two lines go BEFORE the first heartbeat. After it, that heartbeat is judged by the
  # 3-strike rule and the strike it just earned is then reset — §2.2's whole point is lost.
  MARKER_FAILS=0
  MARKER_MAX="$WAIT_MARKER_MAX"
  # ⚠ One heartbeat BEFORE the first sleep. The marker already exists (`heartbeat "running"`
  # runs above the queue loop); what this buys is that `state` does not claim `running` for up
  # to ten minutes while nothing is running. Five readers take `running` to mean "a child
  # session is going right now", and `daily` renders heartbeat age harmlessly — so the human
  # reads a sleeping supervisor as normal progress.
  heartbeat "waiting-for-window-$WIN_TOKEN"
  local n=0
  while ! in_window; do
    # ⚠ 60s, not HEARTBEAT_EVERY. bash defers a trap while a foreground command runs, so a
    # TERM/HUP sent during a sleep is handled only when that sleep returns (measured, and the
    # rate-limit path says the same). Waiting spends nearly all of its time inside `sleep`, so
    # a 600s chunk would delay a `kill` by up to ten minutes. 60s costs nothing.
    # ⚠ NOT `hb_sleep`: it counts DOWN from a total, which machine sleep and DST break, and its
    # state token is hardcoded to the rate-limit one — the behaviour would be right and the
    # reason a lie. Re-asking `in_window` needs no epoch arithmetic at all.
    sleep "$WAIT_CHUNK"
    n=$((n + 1))
    if [ "$((n % 10))" -eq 0 ]; then
      heartbeat "waiting-for-window-$WIN_TOKEN"
    fi
  done
  MARKER_MAX=3
  MARKER_FAILS=0
  echo "[sprint] Window open — resuming."
  # ⚠ Re-check the container. A $TMPDIR container being cleaned is an ordinary event during a
  # run that lasts days, and afterwards every `git -C "$SUP"` fails while the run reports each
  # Issue as "worktree unavailable" (§4.2). `ensure_container` returns 0 when the worktree is
  # registered AND present, so re-entering it is free.
  if ! ensure_container; then
    # ⚠ Clear ISSUE FIRST. This runs at the top of an iteration, so from the second one onward
    # `$ISSUE` still names the PREVIOUS member — and `cleanup`'s P7 reads it. That member is
    # finished; if its last board write happened to fail, the column CACHE still says
    # `in_progress` and P7 would relabel a completed member "interrupted"
    # (04-sprint-window.md §4.2b). Clearing it makes the `${ISSUE:-}` guard do the right thing.
    # ⚠ `HALT_REASON` alone — no `FINISHED`, no marker here. `cleanup` writes
    # `halted:container-lost` because its gate is still open.
    ISSUE=""
    HALT_REASON="container-lost"
    marker_write "halted:container-lost" 2>/dev/null || true
    exit 1
  fi
}
# <!-- /guild:supervisor-core:window -->

# ⚠ The ledger keeps the window as the LITERAL `22:00-10:00`, not the integers: what a resume
# has to restore is the window file, and run.md rebuilds it from this string. Written ONCE at
# run start (it cannot change mid-run) rather than riding along in `heartbeat`.
if [ -n "$WIN_START" ]; then ledger_set window "\"$WIN_RAW\"" 2>/dev/null || true; fi

# ─────────────────────────────────────────────────────────────────────────────
# Main loop (§8.4)
# ─────────────────────────────────────────────────────────────────────────────

ensure_container || exit 1

echo "============================================================"
# ⚠ `(queue may grow)` was FALSE here and is removed: QUEUE is assigned in exactly two places
# and never appended to, and 04-sprint-window.md §2.4's termination proof rests on that.
# batch.md's identical string is TRUE (a parent there spawns children) and is left alone.
echo "  Guild Sprint #$TRACKER: ${#ORDER[@]} member(s)"
# ⚠ Only this script knows `$$`, so the stop instructions are printed here as well as by
# `daily`. Ctrl-C cannot work — a background job of a non-interactive shell inherits SIGINT as
# SIG_IGN and it cannot be trapped or reset — so `kill` is the only way.
echo "  Stop: kill $$ — 대기 중이면 최대 60초, 멤버가 끝난 뒤에 멈춥니다."
echo "        (\`kill -9\` 는 쓰지 마십시오 — 카드가 \`In progress\` 에 남습니다)"
echo "============================================================"
heartbeat "running"

# D11 — the account that `--setup` validated vs the one this run actually has. The
# supervisor inherits the launching session's environment, and `GH_TOKEN` overrides the
# keyring account (measured, §1.1a): every board call then fails for a reason the human
# cannot see. Recorded in the ledger AND echoed: this script's stdout is the supervisor log,
# not a return channel (the LLM reads the marker and the ledger, never this stream).
#
# ⚠ THIS MUST STAY BELOW `heartbeat "running"`. It sat above `RUN_START` in an earlier
# version — before `LEDGER=` was assigned and before `ledger_set` was even defined — so
# bash returned 127 and `2>/dev/null || true` ate it. D11 was dead code under a green
# suite: every board call failed, `board_fails` climbed, and the one key that explains why
# was never written. The stderr redirect is gone for the same reason: if this ever moves
# again it must be loud, not silent.
#
# ⚠ `Active account: true` — not list order. `gh auth status` happens to print the active
# account first in 2.98.0, but that is undocumented and a keyring with three accounts is
# exactly the measured situation (§1.1a).
if [ -n "$BOARD_NUMBER" ] && [ -n "$BOARD_VERIFIED_AS" ]; then
  BOARD_ACTIVE_AS=$(gh auth status 2>/dev/null | "$PY" -c '
import re, sys
active, pending = None, None
for line in sys.stdin:
    m = re.search(r"account\s+(\S+)", line)
    if m:
        pending = m.group(1)
    if "Active account: true" in line and pending:
        active = pending; break
print(active or "")
' || true)
  if [ -n "$BOARD_ACTIVE_AS" ] && [ "$BOARD_ACTIVE_AS" != "$BOARD_VERIFIED_AS" ]; then
    echo "[sprint] NOTE: board account mismatch — $BOARD_ACTIVE_AS != $BOARD_VERIFIED_AS"
    ledger_set board_account_mismatch "\"$BOARD_ACTIVE_AS != $BOARD_VERIFIED_AS\"" || true
  fi
fi

# ⚠ AFTER the account check, BEFORE the queue loop. Resolving node ids needs a working token,
# and every projection point below needs the ids — a projection that runs before this would
# fall into `project_set`'s no-id branch and be counted as a failure. This is also where the
# board can still be switched off cheaply: a project that cannot be read costs one WARN here
# instead of one failed write per member for six hours.
board_resolve
# ⚠ Record WHY the board is off, when it was CONFIGURED but did not come up. Deliberately NOT
# under `BOARD_WAS_ON` — that is 0 precisely in this case. Without it the only signal is an
# `echo` on a stream `daily` states plainly it cannot read, so a six-hour run against an
# untouched board rendered as "투영 기록 없음" — indistinguishable from "the run has not
# started". D9 forbids absorbing the FACT of absorption; this is that fact.
if [ -n "$BOARD_OFF_REASON" ]; then
  ledger_set board_off_reason "\"$BOARD_OFF_REASON\"" 2>/dev/null || true
fi

while [ ${#QUEUE[@]} -gt 0 ]; do
  # ⚠ BEFORE the pop, and this is the only wait point in the file (04-sprint-window.md §0.4).
  # A whole member's life is one iteration, so waiting here satisfies both halves of the
  # requirement for free: a member popped at 09:59 is already inside the loop and runs to the
  # end. AFTER the pop, ISSUE would be assigned while sleeping and `cleanup`'s P7 would read
  # that number. `refresh_base`/`refresh_dag_input` running AFTER the wait is a bonus — a
  # dependency a human merged during the day lands in that night's run.
  wait_for_window
  ISSUE=${QUEUE[0]}; QUEUE=("${QUEUE[@]:1}")
  PROCESSED=$((PROCESSED + 1))

  # 1. blocked?  2. base refresh  3. base decide
  # The guard is NOT optional here either: refresh_dag_input returns non-zero when its python
  # pass fails (corrupt members.json, an unparseable gh payload), and `set -e` would end the
  # entire run with a raw traceback, no `[sprint]` prefix and no failure class. §8.5a's
  # `dag-input-failed` exists for exactly this.
  refresh_dag_input || {
    echo "  ✗ Issue #$ISSUE — DAG input could not be assembled"
    record_failure "$ISSUE" dag-input-failed "refresh_dag_input returned non-zero"
    board_col "$ISSUE" blocked failed:dag-input-failed   # P4
    FAILED=$((FAILED + 1)); FAILED_ISSUES+=("#$ISSUE (dag-input-failed)")
    heartbeat "running"; continue
  }
  # `|| true` is mandatory, not defensive: sprint_dag.py returns MEANINGFUL non-zero codes
  # (base=2 not linearized, depth=4 over cap, cycles=3 found). With `set -e` + `pipefail` an
  # unguarded command substitution in an assignment kills the whole run on those — the
  # supervisor must read the exit code as data, never as a fatal signal.
  BLOCK_LINE="$("$PY" "$DAG" --input "$D/run.json" --mode blocked 2>/dev/null \
                | awk -v i="$ISSUE" '$1==i {print $2}' || true)"
  if [ -n "$BLOCK_LINE" ]; then
    echo "  ⊘ Issue #$ISSUE blocked ($BLOCK_LINE) — skipped"
    record_event "$ISSUE" dependency-blocked "$BLOCK_LINE"
    # ⚠ NOT a projection point — a wait stays in `Ready` (§4.1). But if the PREVIOUS run left
    # this card on `Blocked` with a `failed:<class>`, that class is resolved and the card is
    # lying: `Blocked` means "nothing moves without the human", and `daily` is meanwhile
    # rendering this member under 의존성 차단. The cache is empty on a re-run (truncated at
    # load), so "no cache entry" is exactly "this run has not formed an opinion yet".
    if [ -z "$(board_col_of "$ISSUE")" ]; then board_col "$ISSUE" ready; fi
    BLOCKED=$((BLOCKED + 1)); BLOCKED_ISSUES+=("#$ISSUE ($BLOCK_LINE)")
    continue
  fi

  refresh_base || true
  refresh_dag_input || true
  board_sweep_merged                                                             # P5
  BASE_TOKEN="$("$PY" "$DAG" --input "$D/run.json" --mode base 2>"$D/base.err" \
                | awk -v i="$ISSUE" '$1==i {print $2}' || true)"
  if [ -z "$BASE_TOKEN" ] && [ -s "$D/base.err" ]; then
    echo "  ✗ Issue #$ISSUE base unresolved — $(head -1 "$D/base.err")"
    # A distinct class from the `base-unresolved` BLOCK below: this one means the base
    # DECISION itself failed (bad input, unparseable output), so nothing is known about the
    # dependency and the dependents must not stack on a guess.
    record_failure "$ISSUE" base-decision-failed "$(head -1 "$D/base.err")"
    board_col "$ISSUE" blocked failed:base-decision-failed   # P4
    FAILED=$((FAILED + 1)); FAILED_ISSUES+=("#$ISSUE (base-unresolved)")
    heartbeat "running"; continue
  fi
  case "$BASE_TOKEN" in
    BLOCKED:*)
      echo "  ⊘ Issue #$ISSUE ${BASE_TOKEN} — skipped"
      record_event "$ISSUE" dependency-blocked "$BASE_TOKEN"
      if [ -z "$(board_col_of "$ISSUE")" ]; then board_col "$ISSUE" ready; fi   # see above
      BLOCKED=$((BLOCKED + 1)); BLOCKED_ISSUES+=("#$ISSUE ($BASE_TOKEN)")
      continue ;;
    DEFAULT|"") BASE_REF="origin/$DEFAULT_BRANCH" ;;
    *)
      # A stack base is a BRANCH NAME read back from the dep's PR, and refresh_base only
      # refreshes the default branch. If that branch is not in the shared ref store (it was cut
      # on another machine, or this checkout's copy is stale) fetch it into refs/remotes/ and
      # prefer that — never into a local branch name, which git refuses whenever the branch is
      # checked out in ANY worktree.
      BASE_REF="$BASE_TOKEN"
      if ! git -C "$SUP" rev-parse --verify --quiet "${BASE_REF}^{commit}" >/dev/null 2>&1; then
        git -C "$SUP" fetch --quiet origin \
          "$BASE_TOKEN:refs/remotes/origin/$BASE_TOKEN" 2>/dev/null \
          && BASE_REF="origin/$BASE_TOKEN"
      fi ;;
  esac
  # One check for both shapes. An unresolvable base is BLOCKED, not failed: the dependency
  # simply has not landed anywhere this checkout can see, and `worktree add` would otherwise
  # die with `invalid reference` and be recorded as worktree-create-failed.
  if ! git -C "$SUP" rev-parse --verify --quiet "${BASE_REF}^{commit}" >/dev/null 2>&1; then
    echo "  ⊘ Issue #$ISSUE base $BASE_REF not resolvable — skipped"
    # record_EVENT, not record_failure: this is a BLOCK. Marking it failed would make the DAG
    # treat this Issue as terminal-failed and block everything downstream of it for a reason
    # that is really "the dependency has not landed yet".
    record_event "$ISSUE" base-unresolved "base $BASE_REF resolvable neither locally nor on origin"
    BLOCKED=$((BLOCKED + 1)); BLOCKED_ISSUES+=("#$ISSUE (base-unresolved:$BASE_REF)")
    heartbeat "running"; continue
  fi

  # 4. worktree + memory link + deps
  heartbeat "installing-deps"
  WT="$(worktree_acquire "$ISSUE" "$BASE_REF")" || WT_RC=$?
  if [ "${WT_RC:-0}" -ne 0 ]; then
    WT_MSG="$(head -1 "$D/wt.err" 2>/dev/null || true)"
    if [ "$WT_RC" -eq 2 ]; then
      # Ambiguous branch: a BLOCK, not a failure. The human renames or deletes one branch and
      # re-runs — recording it as failed would mark the Issue terminal and permanently block
      # everything downstream of it for something that takes ten seconds to resolve.
      echo "  ⊘ Issue #$ISSUE blocked — $WT_MSG"
      record_event "$ISSUE" branch-ambiguous "$WT_MSG"
      BLOCKED=$((BLOCKED + 1)); BLOCKED_ISSUES+=("#$ISSUE (branch-ambiguous)")
    else
      echo "  ✗ Issue #$ISSUE worktree unavailable — $WT_MSG"
      record_failure "$ISSUE" worktree-create-failed "$WT_MSG"
      board_col "$ISSUE" blocked failed:worktree-create-failed   # P4
      FAILED=$((FAILED + 1)); FAILED_ISSUES+=("#$ISSUE (worktree-create-failed)")
    fi
    WT_RC=0; heartbeat "running"; continue
  fi
  link_memory "$WT"
  DEPS_LOG="$RUNDIR/deps-${ISSUE}-${TIMESTAMP}.log"
  DEPS_OK=1
  if [ ${#INSTALL_CMDS[@]} -gt 0 ]; then
    : > "$DEPS_LOG"
    for IC in "${INSTALL_CMDS[@]}"; do
      ( cd "$WT" && eval "$IC" ) >> "$DEPS_LOG" 2>&1 || { DEPS_OK=0; break; }
    done
  fi
  if [ "$DEPS_OK" -eq 0 ]; then
    echo "  ✗ Issue #$ISSUE dependency install failed (see $(basename "$DEPS_LOG"))"
    record_failure "$ISSUE" deps-install-failed "see $(basename "$DEPS_LOG")"
    board_col "$ISSUE" blocked failed:deps-install-failed   # P4
    FAILED=$((FAILED + 1)); FAILED_ISSUES+=("#$ISSUE (deps-install-failed)")
    heartbeat "running"; continue
  fi
  heartbeat "running"

  RESUME_TRIES=0; RL_TRIES=0; ATTEMPT=0
  # A value no child count can equal, so the first pass always reads as progress without
  # SPLIT_PREV having to double as a sentinel (that dual role was BLOCKER B1).
  SPLIT_PREV=999999; SPLIT_STALL=0; SPLIT_PASSES=0
  RETRIES="$(ledger_get "retries.$ISSUE" 0)"
  echo "[$PROCESSED/$TOTAL] Issue #$ISSUE → base $BASE_REF → $WT"

  while true; do
    ATTEMPT=$((ATTEMPT + 1))
    LOG="$RUNDIR/issue-${ISSUE}-${TIMESTAMP}-attempt${ATTEMPT}.log"
    EXIT_CODE=0
    # The child runs IN the issue worktree — this subshell is what makes §8.1a's isolation
    # real. Without it the child runs in the supervisor worktree, which has no dependencies
    # installed, and every test fails while the design silently reverts to one checkout.
    # P1 (03-sprint-board.md §5.2). Not a derivation — the supervisor KNOWS it is about to
    # develop this member. Fires again on every retry because it sits inside the retry loop,
    # which is what the column cache is for. The reason is cleared with it: a stale
    # `failed:<class>` from a previous attempt must not sit on an in-progress card.
    board_col "$ISSUE" in_progress
    ( cd "$WT" && GLD_UNATTENDED=1 GLD_SPRINT_BASE="$BASE_REF" \
        CLAUDE_CODE_PRINT_BG_WAIT_CEILING_MS=0 \
        claude -p --verbose --output-format stream-json --dangerously-skip-permissions \
        "/gld dev $ISSUE" ) > "$LOG" 2>&1 || EXIT_CODE=$?

    if [ "$EXIT_CODE" -eq 0 ]; then
      # <!-- guild:supervisor-core:arms -->
      # exit 0 is NOT proof of completion — a headless turn can end while a backgrounded
      # pre-commit hook leaves the Issue mid-spine with no commit/PR. Truth = the GitHub label
      # (_handoff.md Section A: "labels are the state").
      #
      # Arm order is the shell-side twin of Section A's canonical stage derivation. A generated
      # .sh cannot use that jq projection, so the rule appears here as `case` ordering:
      # guild:needs-human MUST be tested BEFORE guild:done AND guild:children, because bash
      # `case` fires the FIRST matching arm and those labels coexist on one Issue.
      STATE=$(gh issue view "$ISSUE" --repo "$OWNER_REPO" --json labels \
        --jq '[.labels[].name] | map(select(startswith("guild:"))) | join(",")' 2>/dev/null || true)
      case "$STATE" in
        *guild:needs-human*)
          echo "  ⏸ Issue #$ISSUE paused (needs-human)"; PAUSED=$((PAUSED + 1))
          PAUSED_ISSUES+=("#$ISSUE")
          board_col "$ISSUE" blocked needs-human                                  # P2
          break ;;
        *guild:done*)
          echo "  ✓ Issue #$ISSUE done"; DONE=$((DONE + 1))
          # P3 — refresh FIRST. The PR this session just opened is not in the snapshot taken
          # at the top of this iteration, so judging "has its own PR" without refreshing
          # classifies EVERY normal member as a split parent.
          # ⚠ INSIDE the board guard. This refresh exists only to make P3's judgement right;
          # it costs `gh pr list` + `gh issue list` per completed member, and the arm `break`s
          # immediately afterwards so the next iteration refreshes anyway. Outside the guard,
          # board-off users paid two extra API calls per member for a decision never made —
          # in a loop that has its own `rate-limit-exhausted` failure class.
          if [ -n "$BOARD_NUMBER" ]; then
            refresh_dag_input || true
            BOARD_PRS=$("$PY" -c 'import json,sys;d=json.load(open(sys.argv[1]));print(len(d.get("prs") or []))' "$D/run.json" 2>/dev/null || echo 0)
            BOARD_MINE=$("$PY" -c 'import json,sys;d=json.load(open(sys.argv[1]));print(sum(1 for p in (d.get("prs") or []) if str(p.get("issue"))==sys.argv[2]))' "$D/run.json" "$ISSUE" 2>/dev/null || echo 0)
            if [ "$BOARD_MINE" -gt 0 ]; then
              board_col "$ISSUE" in_review
            elif [ "$BOARD_PRS" -gt 0 ]; then
              # Done with no PR of its own = finished by a design-time split; its children
              # carry the PRs and they are not members, so this card cannot reach Done on
              # its own (§5.4). The token is how the human learns there is anything to review.
              board_col "$ISSUE" in_review split-children
            else
              # `prs` empty for EVERYONE — `gh pr list` failed and was replaced with `[]`
              # while still returning 0. Do not assert a split that we cannot see — but do not
              # stay silent either: with no reason token this card is indistinguishable from a
              # normal reviewed-and-waiting member, so a failed PR read would read as "there is
              # a PR here, go review it". `pr-unknown` says which of the two it is.
              board_col "$ISSUE" in_review pr-unknown
            fi
          fi
          board_sweep_merged                                                       # P5
          worktree_release "$ISSUE"
          break ;;
        *guild:children*)
          # A split that is still mid-orchestration. NOT terminal, and NOT handed to the human:
          # re-invoking `/gld dev <parent>` IS the way to continue it. dev.md Phase 1 sends a
          # parent at guild:children straight to Phase 2b, and Phase 2b drives only the children
          # that are NOT yet guild:done — so each attempt resumes exactly where the last stopped
          # and Phase 2c finally flips the parent to guild:done (removing guild:needs-human).
          #
          # Isolation still holds where this design promises it: one worktree per sprint MEMBER.
          # A split's children are that member's own work and share its worktree, which is the
          # same checkout `dev` would use outside a sprint.
          #
          # The bound is PROGRESS, not attempts. A parent with five children legitimately needs
          # several sessions, and a fixed cap of 2 would abandon one that was advancing. Count
          # the children still outstanding; reset the counter whenever that number falls.
          # ⚠ THREE guards, because the progress bound alone loops forever (all measured):
          #   (a) an ABSOLUTE ceiling. A count that OSCILLATES (3→2→3→2) resets the stall
          #       counter on every decrease, so "progress" never runs out. 62 sessions and
          #       still going.
          #   (b) `-1` (unknown) counts as NO progress. It used to leave SPLIT_PREV empty, and
          #       an empty SPLIT_PREV read as "first pass" on every pass. 79 sessions.
          #   (c) SPLIT_PREV starts at a value no count can equal, so it is a stored number and
          #       nothing else — it used to double as the "first pass" sentinel, which is what
          #       made (b) unbounded.
          SPLIT_PASSES=$((SPLIT_PASSES + 1))
          SPLIT_LEFT="$(children_pending "$ISSUE")"
          if [ "$SPLIT_LEFT" -lt 0 ]; then
            SPLIT_STALL=$((SPLIT_STALL + 1))
            SPLIT_DESC="unknown"
          else
            if [ "$SPLIT_LEFT" -lt "$SPLIT_PREV" ]; then SPLIT_STALL=0
            else SPLIT_STALL=$((SPLIT_STALL + 1)); fi
            SPLIT_PREV="$SPLIT_LEFT"
            SPLIT_DESC="$SPLIT_LEFT"
          fi
          if [ "$SPLIT_STALL" -le 2 ] && [ "$SPLIT_PASSES" -le 12 ]; then
            echo "  ↻ Issue #$ISSUE is a split parent — $SPLIT_DESC child(ren) outstanding, continuing (stall $SPLIT_STALL/2, pass $SPLIT_PASSES/12)"
            RETRIES=$((RETRIES + 1)); ledger_set "retries.$ISSUE" "$RETRIES"
            continue
          fi
          echo "  ⚠ Issue #$ISSUE INCOMPLETE — split orchestration stopped advancing ($SPLIT_DESC child(ren) left after $SPLIT_PASSES passes)"
          record_failure "$ISSUE" split-stalled "$SPLIT_DESC child(ren) outstanding after $SPLIT_PASSES passes (stall $SPLIT_STALL)"
          board_col "$ISSUE" blocked failed:split-stalled   # P4
          INCOMPLETE=$((INCOMPLETE + 1)); INCOMPLETE_ISSUES+=("#$ISSUE (split: $SPLIT_DESC left)"); break ;;
        *)
          RESUME_TRIES=$((RESUME_TRIES + 1))
          if [ "$RESUME_TRIES" -le 2 ]; then
            echo "  ↻ Issue #$ISSUE exited at [${STATE:-unknown}] without finishing — re-resuming ($RESUME_TRIES/2)"
            RETRIES=$((RETRIES + 1)); ledger_set "retries.$ISSUE" "$RETRIES"
            continue
          fi
          echo "  ⚠ Issue #$ISSUE INCOMPLETE (stuck at ${STATE:-unknown} after re-resume)"
          record_failure "$ISSUE" incomplete-mid-spine "stuck at ${STATE:-unknown} after $RESUME_TRIES re-resumes"
          board_col "$ISSUE" blocked failed:incomplete-mid-spine   # P4
          INCOMPLETE=$((INCOMPLETE + 1)); INCOMPLETE_ISSUES+=("#$ISSUE (${STATE:-unknown})"); break ;;
      esac
      # <!-- /guild:supervisor-core:arms -->
    fi

    RESET_AT=$(jq -r 'select(.type == "rate_limit_event") | .rate_limit_info | select(.status != "allowed") | .resetsAt // empty' "$LOG" 2>/dev/null | tail -1 || true)
    # <!-- guild:supervisor-core:ratelimit -->
    # Rate-limit DETECTION + WAIT computation — VERBATIM-shared with batch.md's supervisor
    # (tests/sprint_supervisor_test.sh compares them byte-for-byte after indent normalisation).
    # This is where the two measured bug fixes live: the "rate[ -]limit" regex that must not
    # match the literal field name `rate_limit_event`, and the all-digit guard on `resetsAt`.
    # The sleep and the give-up branch are OUTSIDE, deliberately — see hb_sleep and below.
    RATE_LIMITED=0
    if [ -n "$RESET_AT" ]; then RATE_LIMITED=1; fi
    # Fallback text scan: a genuinely rate-limited log that carried NO structured
    # rate_limit_event (a plain-text message). ⚠ An earlier version re-ran the *identical* jq
    # here, which by construction returns empty a second time — so the exact case this fallback
    # exists for fell straight through to "genuine failure" and was counted FAILED. Mark it
    # rate-limited and back off on a schedule instead, since no resetsAt is available.
    # "rate[ -]limit" (space/hyphen only, not an unescaped dot) avoids matching the literal JSON
    # field name "rate_limit_event", which appears on every log carrying a routine
    # status:"allowed" telemetry event — that false match once sent a genuine unrelated crash
    # into an uncapped retry loop.
    if [ "$RATE_LIMITED" -eq 0 ] && grep -qi "rate[ -]limit\|overloaded\|too many requests" "$LOG" 2>/dev/null; then
      RATE_LIMITED=1
    fi
    if [ "$RATE_LIMITED" -eq 1 ]; then
      WAIT=""
      # resetsAt is not guaranteed to be epoch seconds. An ISO-8601 value would make the
      # arithmetic below fail (or silently evaluate to nonsense), so only trust an all-digit
      # value and fall back to the backoff otherwise.
      case "$RESET_AT" in
        ''|*[!0-9]*) ;;
        *) NOW=$(date +%s); WAIT=$((RESET_AT - NOW + 30)) ;;
      esac
      # <!-- /guild:supervisor-core:ratelimit -->
      # Below is per-supervisor: the give-up accounting uses this design's failure-class
      # vocabulary (§8.5a `rate-limit-exhausted`), which batch has no concept of. Diffing the
      # two real scripts is what showed the verbatim region has to stop here — it cannot
      # include a branch that records into a per-design taxonomy.
      # RL_TRIES must advance on EVERY rate-limit encounter, not only when no reset time was
      # reported. Incrementing it inside the no-reset branch meant an API that keeps returning
      # `resetsAt` never reached the cap of 6 — the Issue retried without limit.
      RL_TRIES=$((RL_TRIES + 1))
      if [ "$RL_TRIES" -gt 6 ]; then
        echo "  ✗ Issue #$ISSUE still rate limited after $RL_TRIES waits — giving up this run"
        record_failure "$ISSUE" rate-limit-exhausted "still rate limited after $RL_TRIES waits"
        board_col "$ISSUE" blocked failed:rate-limit-exhausted   # P4
        FAILED=$((FAILED + 1)); FAILED_ISSUES+=("#$ISSUE (rate-limit-exhausted)"); break
      fi
      # A `resetsAt` in MILLISECONDS is all digits, so it passes the guard inside the verbatim
      # core above and yields a wait of ~56,000 years (measured). An unbounded wait is worse
      # than a wrong one: hb_sleep keeps writing heartbeats, so §8.2's duplicate-run guard reads
      # the hung run as healthy and the sprint cannot be resumed without killing it by hand.
      if [ -n "$WAIT" ] && [ "$WAIT" -gt "$WAIT_MAX" ]; then
        echo "  ⚠ Reported reset is implausible (${WAIT}s > ${WAIT_MAX}s) — using the backoff instead"
        WAIT=""
      fi
      if [ -z "$WAIT" ] || [ "$WAIT" -le 0 ]; then
        WAIT=$((RL_TRIES * 300))
        echo "  ⏳ Rate limited, no usable reset time. Backing off ${WAIT}s ($RL_TRIES/6)..."
      else
        RESET_TIME=$(date -r "$RESET_AT" +%H:%M:%S 2>/dev/null || date -d "@$RESET_AT" +%H:%M:%S 2>/dev/null || echo "?")
        echo "  ⏳ Rate limited. Waiting until ~$RESET_TIME ($((WAIT/60))m $((WAIT%60))s)..."
      fi
      heartbeat "rate-limited-until-$(( $(date +%s) + WAIT ))"
      hb_sleep "$WAIT"
      heartbeat "running"
      echo "  🔄 Retrying Issue #$ISSUE (resume from GitHub state)..."
      RETRIES=$((RETRIES + 1)); ledger_set "retries.$ISSUE" "$RETRIES"
      continue
    fi

    echo "  ✗ Issue #$ISSUE failed (exit $EXIT_CODE)"; FAILED=$((FAILED + 1))
    REASON=$(jq -r 'select(.type == "result") | select(.is_error == true) | .result // empty' "$LOG" 2>/dev/null | tail -1 | cut -c1-80 || true)
    record_failure "$ISSUE" child-session-failed "${REASON:-exit $EXIT_CODE}"
    board_col "$ISSUE" blocked failed:child-session-failed   # P4
    # ⚠ The CLASS, not `$REASON`. This array becomes the ledger's `completion.failed_issues`
    # (04-sprint-window.md §4.3), and `marker_write` renders the whole ledger into a GitHub
    # issue comment — `$REASON` is 80 raw characters of the child session's error result and can
    # carry paths, stack frames or an API body. INV5 forbids that leaving the machine
    # un-sanitised. The raw text stays local, in `failures.jsonl` (`record_failure` above) and
    # on this stdout. Every other arm in this loop already appends a class.
    FAILED_ISSUES+=("#$ISSUE (child-session-failed)")
    break
  done

  # Sub-issues discovered during the run: RECORD them. They are NOT queued as members.
  #
  # ⚠ Queuing them was wrong and measured so. A child is not a sprint member: it has no row in
  # the immutable member table, so `--mode base` has no line for it, `BASE_TOKEN` comes back
  # empty, and it was developed on the default branch — losing the parent's place in the stack.
  # Worse, the empty token made its fate depend on whether `$D/base.err` happened to be
  # non-empty, so ONE unrelated warning about ANOTHER member failed every child in the run.
  #
  # `dev.md` Phase 2b is what develops them, inside the parent's own worktree, resumed by the
  # guild:children arm above. Recording them here is for reporting only: `daily` and `retro`
  # fold child PRs into the sprint's accounting, and a crash cannot re-derive the set from
  # GitHub — design.md/plan.md give a child only `Parent Issue: #N`, never `Sprint: #<tracker>`.
  if [ -n "$OWNER_REPO" ]; then
    CHILDREN=$(gh issue list --repo "$OWNER_REPO" --label guild:child --state all --limit 200 \
      --json number,body,labels \
      --jq "[.[] | select((.body // \"\") | test(\"Parent Issue: #${ISSUE}([^0-9]|\$)\")) | select((.labels // []) | map(.name) | index(\"guild:done\") | not)] | .[].number" 2>/dev/null || true)
    for C in $CHILDREN; do
      # A non-numeric value here would be interpolated into a regex, a path and a queue.
      case "$C" in ''|*[!0-9]*) continue ;; esac
      case "$SEEN" in *" #$C "*) ;; *)
        SEEN="$SEEN #$C "
        DISC="$(ledger_get discovered '[]')"
        # ⚠ Compute first, and write only on success. Inlining the substitution meant a failure
        # here stored an EMPTY STRING where run.md Phase 1.5 expects a list — a type error in
        # the one field a crash cannot re-derive from GitHub (a child carries only
        # `Parent Issue: #N`, never `Sprint: #<tracker>`).
        NEWDISC="$("$PY" -c 'import json,sys; a=json.loads(sys.argv[1]); a.append(int(sys.argv[2])); print(json.dumps(sorted(set(a))))' "$DISC" "$C" 2>/dev/null || true)"
        case "$NEWDISC" in
          \[*\]) ledger_set discovered "$NEWDISC" ;;
          *) echo "  ⚠ could not record discovered child #$C in the ledger — a crash will not re-find it" ;;
        esac
        echo "  + Discovered child #$C (developed by its parent's split orchestration)" ;;
      esac
    done
  fi
  heartbeat "running"
done

# P6 (03-sprint-board.md §5.2) — the queue loop is over. `run.json` was last written at the
# TOP of the final member's iteration, so a PR opened or merged during that session is not
# in it; refresh once more or this is a no-op. ⚠ MUST run before the teardown below:
# `refresh_dag_input` reads `git -C "$SUP" branch`, and $SUP is removed there.
if [ -n "$BOARD_NUMBER" ]; then
  refresh_dag_input || true
  board_sweep_merged
  # ⚠ A dependency wait is `Ready` DURING the run — "Guild is waiting and it resolves itself".
  # The moment the queue drains that stops being true: the dependency did not land, so these
  # members will not move again without the human. Leaving them in `Ready` makes the board's
  # largest end-of-run pile say "queued, nothing for you to do" (§4.1's definition) about work
  # that is dead until someone repairs the parent — and that pile is biggest exactly when a
  # foundational member failed early. This is a terminal fact known here, needing no new read.
  # ⚠ The token must match the actual block class. `BLOCKED_ISSUES` also collects
  # `#N (branch-ambiguous)` and `#N (base-unresolved:<ref>)`, and those are NOT dependency
  # waits — the repair for branch-ambiguous is deleting one of two candidate branches, so
  # telling the human "your dependency never landed" points at the wrong thing.
  for bi in ${BLOCKED_ISSUES[@]+"${BLOCKED_ISSUES[@]}"}; do
    case "$bi" in
      \#*) BOARD_BI="${bi#\#}"; BOARD_BI="${BOARD_BI%% *}"
           case "$bi" in
             *"(branch-ambiguous)"*)  board_col "$BOARD_BI" blocked branch-ambiguous ;;
             *"(base-unresolved"*)    board_col "$BOARD_BI" blocked base-unresolved ;;
             *)                       board_col "$BOARD_BI" blocked dep-unresolved ;;
           esac ;;
    esac
  done
fi

# Container teardown. Order matters: prune BEFORE removing the supervisor worktree, and never
# from inside it — this script never cd's into the container, so `git -C "$HUMAN_REPO"` is
# always usable even after $SUP is gone. ⚠ $D survives until after the final marker write.
prune_safe
if [ -d "$SUP" ]; then
  git -C "$HUMAN_REPO" worktree remove "$SUP" 2>/dev/null \
    || echo "[sprint] supervisor worktree kept at $SUP (not clean)"
fi
prune_safe
rmdir "$CONTAINER" 2>/dev/null || true

RUN_ELAPSED=$(( $(date +%s) - RUN_START ))
TOTAL_IN=0; TOTAL_OUT=0; TOTAL_CR=0; TOTAL_CC=0; TOTAL_COST="0"
for L in "$RUNDIR"/issue-*-"${TIMESTAMP}"-attempt*.log; do
  [ -f "$L" ] || continue
  S=$(jq -r 'select(.type=="result") | "\(.usage.input_tokens // 0) \(.usage.output_tokens // 0) \(.usage.cache_read_input_tokens // 0) \(.usage.cache_creation_input_tokens // 0) \(.total_cost_usd // 0)"' "$L" 2>/dev/null | tail -1 || true)
  [ -n "$S" ] && read -r IN OUT CR CC COST <<< "$S" && {
    TOTAL_IN=$((TOTAL_IN + ${IN:-0})); TOTAL_OUT=$((TOTAL_OUT + ${OUT:-0}))
    TOTAL_CR=$((TOTAL_CR + ${CR:-0})); TOTAL_CC=$((TOTAL_CC + ${CC:-0}))
    TOTAL_COST=$(echo "$TOTAL_COST + ${COST:-0}" | bc 2>/dev/null || echo "$TOTAL_COST")
  }
done

echo "============================================================"
echo "  Guild Sprint #$TRACKER — run complete"
echo "  Total: $PROCESSED  Done: $DONE  Paused: $PAUSED  Blocked: $BLOCKED  Incomplete: $INCOMPLETE  Failed: $FAILED"
if [ ${#BLOCKED_ISSUES[@]} -gt 0 ]; then
  echo "  Blocked (a dependency did not land — not a failure):"
  for BI in "${BLOCKED_ISSUES[@]}"; do echo "    $BI"; done
fi
if [ ${#INCOMPLETE_ISSUES[@]} -gt 0 ]; then
  echo "  Incomplete (exited without reaching guild:done):"
  for II in "${INCOMPLETE_ISSUES[@]}"; do echo "    $II"; done
fi
if [ ${#FAILED_ISSUES[@]} -gt 0 ]; then
  echo "  Failed:"; for FI in "${FAILED_ISSUES[@]}"; do echo "    $FI"; done
fi
if [ ${#KEPT_WORKTREES[@]} -gt 0 ]; then
  echo "  Worktrees kept (git refused removal — check whether it is source or just docs):"
  for KW in "${KEPT_WORKTREES[@]}"; do echo "    $KW"; done
fi
echo "  Time: $((RUN_ELAPSED/60))m $((RUN_ELAPSED%60))s  Cost: \$${TOTAL_COST}"
echo "  Tokens: in $TOTAL_IN · out $TOTAL_OUT · cache read $TOTAL_CR · create $TOTAL_CC"
echo "  Logs: $RUNDIR/   ·   Status: /gld sprint daily"
echo "============================================================"
# ⚠ `finished` is written BEFORE $D is removed. marker_write's own scratch files live in $D,
# so the earlier order (rm first) made this call fail silently and left the marker on the last
# `running` heartbeat: `daily` then rendered a completed sprint as in-flight, and the
# duplicate-run guard read it as crash residue.
# ⚠ Refresh the board counters BEFORE the marker. `marker_write` renders from the ledger, and
# the last `heartbeat` happened before P6's sweep — so a run whose final `Done` writes all
# failed (scope revoked late, rate limit at the end) recorded `board_fails: 0` and then
# `daily`/`run` Phase 4 stated "보드: 실패 0건" over a board that never got the last column.
# `cleanup` already does this before `halted:interrupted`; the clean-exit path did not.
if [ "$BOARD_WAS_ON" = 1 ]; then
  ledger_set board_fails "$BOARD_FAILS" 2>/dev/null || true
  ledger_set board_bugs "$BOARD_BUGS" 2>/dev/null || true
  ledger_set board_unknown_col "$BOARD_UNKNOWN_COL" 2>/dev/null || true
fi
# ⚠ BEFORE `marker_write "finished"` and AFTER the counter flush. On a clean run `rm -rf "$D"`
# below deletes the ledger file, so anything that does not make it onto the marker is lost for
# good — and the marker is rendered from the ledger by that very call. There is NO completion
# notification (Phase 4 only runs while the launching session is alive, and the marker is a
# PATCH of an existing comment, so GitHub sends nothing): this key is what `/gld sprint daily`
# reads days later. §4.3.
# ⚠ EVERY PATH IS RELATIVE. `marker_write` PATCHes the whole ledger into a GitHub issue
# comment, so an absolute path publishes `/Users/<name>/…` and the repo's parent layout to a
# possibly public repo — INV5. No ledger key has ever carried a path before this one.
# ⚠ `kept_worktrees` keeps git's REFUSAL REASON, not just the path: `locked` /
# `modified or untracked files` / `main working tree` need different actions and cannot be
# re-derived days later. (Known gap, inherited: `worktree_release` only runs at `guild:done`,
# so a PAUSED member's preserved worktree is not in this list.)
# ⚠ The arrays go through FILES, and the python goes through a heredoc that is NOT inside a
# `$( … )`. Both are measured constraints of this file: bash mis-parses parentheses and quotes
# in a heredoc nested in a command substitution (see this file's header and `marker_write`),
# and `"$(printf … "${ARR[@]}")"` on the same line as the heredoc is exactly that nesting.
: > "$D/comp_failed.txt"; : > "$D/comp_incomplete.txt"
: > "$D/comp_blocked.txt"; : > "$D/comp_paused.txt"; : > "$D/comp_kept.txt"
for X in ${FAILED_ISSUES[@]+"${FAILED_ISSUES[@]}"};     do printf '%s\n' "$X" >> "$D/comp_failed.txt"; done
for X in ${INCOMPLETE_ISSUES[@]+"${INCOMPLETE_ISSUES[@]}"}; do printf '%s\n' "$X" >> "$D/comp_incomplete.txt"; done
for X in ${BLOCKED_ISSUES[@]+"${BLOCKED_ISSUES[@]}"};   do printf '%s\n' "$X" >> "$D/comp_blocked.txt"; done
for X in ${PAUSED_ISSUES[@]+"${PAUSED_ISSUES[@]}"};     do printf '%s\n' "$X" >> "$D/comp_paused.txt"; done
# ⚠ Two files, same index — see KEPT_WT_ISSUE's declaration. Never re-split the folded string.
for X in ${KEPT_WT_ISSUE[@]+"${KEPT_WT_ISSUE[@]}"};     do printf '%s\n' "$X" >> "$D/comp_kept_issue.txt"; done
for X in ${KEPT_WT_REASON[@]+"${KEPT_WT_REASON[@]}"};   do printf '%s\n' "$X" >> "$D/comp_kept_reason.txt"; done
"$PY" - "$D" "$RUNDIR" "$HUMAN_REPO" "$CONTAINER" "$TIMESTAMP" \
  "$PROCESSED" "$DONE" "$PAUSED" "$BLOCKED" "$INCOMPLETE" "$FAILED" \
  "$RUN_ELAPSED" "$TOTAL_COST" "$TOTAL_IN" "$TOTAL_OUT" "$TOTAL_CR" "$TOTAL_CC" \
  > "$D/completion.json" 2>/dev/null <<'PY' || true
import json, os, sys
(d, rundir, human, container, stamp, total, done, paused, blocked, incomplete, failed,
 elapsed, cost, tin, tout, tcr, tcc) = sys.argv[1:18]
def lines(name):
    try:
        with open(os.path.join(d, name)) as fh:
            return [l.strip() for l in fh if l.strip()]
    except Exception:
        return []
def rel(path, base):
    try:
        r = os.path.relpath(path, base)
    except Exception:
        return os.path.basename(path)
    return r if not r.startswith("..") else os.path.basename(path)
# ⚠ NO worktree path. The container is a SIBLING of the checkout (or `$TMPDIR`), so no
# `$HUMAN_REPO`-relative form exists in every case, and `daily` already has the live absolute
# paths from `git worktree list --porcelain` — it joins on the issue number (§4.3 · INV5).
kept = [{"issue": i, "reason": r}
        for i, r in zip(lines("comp_kept_issue.txt"), lines("comp_kept_reason.txt"))]
print(json.dumps({
    "total": int(total), "done": int(done), "paused": int(paused),
    "blocked": int(blocked), "incomplete": int(incomplete), "failed": int(failed),
    "elapsed_s": int(elapsed), "cost": cost,
    "tokens": {"in": int(tin), "out": int(tout),
               "cache_read": int(tcr), "cache_create": int(tcc)},
    "logs": rel(rundir, human), "run_timestamp": stamp,
    "failed_issues": lines("comp_failed.txt"),
    "incomplete_issues": lines("comp_incomplete.txt"),
    "blocked_issues": lines("comp_blocked.txt"),
    "paused_issues": lines("comp_paused.txt"),
    "kept_worktrees": kept,
}, sort_keys=True))
PY
if [ -s "$D/completion.json" ]; then
  ledger_set completion "$(cat "$D/completion.json")" 2>/dev/null || true
fi
marker_write "finished" || echo "[sprint] WARN: could not record state:finished"
FINISHED=1

# Self-delete only when the queue drained with nothing to come back to. A run that ended with
# failures, incompletes or blocks KEEPS its script — that script is the record of what it was
# going to do, and re-running it is how the human continues (§8.6). Setting COMPLETED
# unconditionally meant a run that failed every single Issue deleted its own evidence.
if [ "$((FAILED + INCOMPLETE + BLOCKED))" -eq 0 ]; then
  COMPLETED=1
  # ⚠ And ONLY THEN remove $D. It holds `members.json` — the queue's own input, written by
  # run.md Phase 3 and never regenerated by this script — plus the ledger's retries/discovered.
  # Removing it unconditionally made the KEPT script unrunnable: re-running it reported
  # `DAG input could not be assembled` and failed every Issue (measured), which contradicts the
  # very reason the script is kept. Tidiness is worth nothing if it deletes the checkpoint.
  rm -rf "$D"
else
  echo "[sprint] $((FAILED + INCOMPLETE + BLOCKED)) issue(s) did not finish — keeping the script and $D for re-run"
fi
